tes":10,"result":"Hemoglobin 13,1 g/dL; bạch cầu 6,4 G/L; tiểu cầu 258 G/L."},{"name":"CRP","duration_minutes":10,"result":"CRP 1,2 mg/L; giới hạn tham chiếu của phòng xét nghiệm dưới 5 mg/L."},{"name":"Kháng thể tTG-IgA và IgA toàn phần","duration_minutes":10,"result":"tTG-IgA âm tính; IgA toàn phần trong giới hạn tham chiếu."},{"name":"","duration_minutes":40,"result":"Không thực hiện: chưa có dữ kiện đặt ra chỉ định trong tình huống này."}],"choices":{"diagnosis":{"ydx":["Bệnh Crohn","Viêm ruột nhiễm khuẩn cấp","Ung thư đại trực tràng","Hội chứng ruột kích thích"]},"actions":["Điều chỉnh chế độ ăn và thuốc theo triệu chứng nổi trội","Giải thích bệnh và thống nhất kế hoạch theo dõi","Ghi nhật ký triệu chứng, bữa ăn và dạng phân","Chỉ định nội soi định kỳ bất kể triệu chứng và dấu báo động"]}}'::jsonb,
  'a40867345b02b686886b4a0f3e3598b83d0aec4ea32746f4212d08027f923737'
)
