  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thượng vị tái diễn ở người bệnh có loét tá tràng","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":37,"sex":"nam","patient_label":"Người bệnh mô phỏng N02"},"presentation":{"intro":"Người bệnh khám Nội vì đau thượng vị tái diễn trong 6 tuần, chưa có dấu xuất huyết.","place":null,"clock":null,"night":false},"vitals":{"hr":80,"sbp":118,"dbp":76,"rr":17,"temperature_c":36.6,"spo2":98},"history":[{"question":"Đau có tính chất và thời điểm thế nào?","response":"Đau âm ỉ hoặc nóng rát thượng vị, đôi khi lúc đói và ban đêm."},{"question":"Có nôn máu hoặc đi phân đen không?","response":"Không nôn máu, phân không đen."},{"question":"Có sụt cân, nuốt nghẹn hoặc nôn kéo dài không?","response":"Không có các triệu chứng này."},{"question":"Có dùng thuốc giảm đau chống viêm hoặc aspirin không?","response":"Không dùng gần đây."},{"question":"Đã điều trị H. pylori hoặc dùng kháng sinh nào chưa?","response":"Chưa điều trị H. pylori; không nhớ đầy đủ các đợt kháng sinh trước đây."},{"question":"Có dị ứng thuốc không?","response":"Không ghi nhận dị ứng thuốc."},{"question":"Có hút thuốc không?","response":"Hút khoảng 5 điếu/ngày."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, da niêm hồng, không dấu mất nước."},{"group":"K","item":"Khám bụng","finding":"Ấn đau nhẹ thượng vị; bụng mềm, không đề kháng hoặc co cứng."},{"group":"K","item":"Tim và phổi","finding":"Không ghi nhận bất thường."},{"group":"K","item":"Dấu biến chứng","finding":"Không dấu giảm tưới máu hoặc phản ứng phúc mạc."}],"investigations":[{"name":"Nội soi tiêu hóa trên","duration_minutes":20,"result":"Ổ loét hành tá tràng 7 mm, đáy sạch, không chảy máu."},{"name":"Xét nghiệm urease nhanh từ mẫu sinh thiết dạ dày","duration_minutes":10,"result":"Dương tính với H. pylori."},{"name":"Công thức máu","duration_minutes":10,"result":"Hemoglobin 14,2 g/dL, không thiếu máu."},{"name":"CT bụng để xác nhận H. pylori","duration_minutes":40,"result":"Không thực hiện: không phù hợp mục đích chẩn đoán H. pylori."}],"choices":{"diagnosis":{"ydx":["Viêm túi mật cấp","Tắc ruột cơ học","Loét tá tràng có nhiễm H. pylori, chưa có biến chứng","Viêm tụy cấp"]},"actions":["Dùng kháng thể H. pylori huyết thanh làm bằng chứng chắc chắn đã khỏi","Rà tiền sử kháng sinh, dị ứng và khả năng tuân thủ","Hẹn kiểm tra tiệt trừ ít nhất 4 tuần sau kháng sinh và ngừng PPI 2 tuần trước xét nghiệm theo hướng dẫn","Lựa chọn phác đồ tiệt trừ phù hợp dữ liệu kháng thuốc và hướng dẫn địa phương"]}}'::jsonb,
