  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thượng vị cấp lan ra sau lưng","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":46,"sex":"nam","patient_label":"Người bệnh mô phỏng N03"},"presentation":{"intro":"Người bệnh đến cấp cứu vì đau thượng vị dữ dội 10 giờ, kèm nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":108,"dbp":68,"rr":22,"temperature_c":37.8,"spo2":97},"history":[{"question":"Đau khởi phát và lan thế nào?","response":"Đau thượng vị liên tục, lan ra sau lưng, mức độ 8/10."},{"question":"Có nôn, nôn xong có giảm đau không?","response":"Nôn 4 lần, đau không giảm sau nôn."},{"question":"Có đau ngực, khó thở hoặc vã mồ hôi không?","response":"Không đau ngực, hơi mệt, không khó thở rõ."},{"question":"Có tiền sử sỏi mật hoặc vàng da không?","response":"Chưa ghi nhận sỏi mật; không vàng da trước đợt này."},{"question":"Uống rượu bia thế nào?","response":"Uống nhiều năm; gần đây uống lượng lớn trước khi xuất hiện triệu chứng."},{"question":"Còn trung tiện và đi tiêu không?","response":"Vẫn trung tiện; lần đi tiêu cuối vào sáng cùng ngày."},{"question":"Có bệnh tim, bệnh thận hoặc dùng thuốc mới không?","response":"Chưa ghi nhận bệnh tim, thận; không dùng thuốc mới."}],"examination":[{"group":"K","item":"Toàn trạng và tưới máu","finding":"Tỉnh, môi hơi khô, đầu chi ấm, thời gian làm đầy mao mạch khoảng 2 giây."},{"group":"K","item":"Khám bụng","finding":"Ấn đau thượng vị, chướng nhẹ, không co cứng thành bụng."},{"group":"K","item":"Tim và phổi","finding":"Tim nhanh đều, phổi chưa có ran."},{"group":"K","item":"Da và củng mạc","finding":"Không vàng da; không bầm quanh rốn hoặc hai hông."}],"investigations":[{"name":"Lipase máu","duration_minutes":10,"result":"Lipase 780 U/L; giới hạn trên của phòng xét nghiệm 60 U/L."},{"name":"Chức năng thận, điện giải và công thức máu","duration_minutes":10,"result":"Creatinin 94 µmol/L; kali 3,4 mmol/L; hematocrit 45%."},{"name":"Siêu âm bụng, xét nghiệm gan mật và triglycerid","duration_minutes":15,"result":"Không thấy sỏi túi mật hoặc giãn đường mật; triglycerid 1,9 mmol/L; bilirubin không tăng."},{"name":"ECG và troponin độ nhạy cao theo quy trình cấp cứu","duration_minutes":3,"result":"ECG không có biến đổi thiếu máu cơ tim; troponin nối tiếp không tăng theo ngưỡng phòng xét nghiệm."},{"name":"CT bụng có cản quang thường quy ngay để phân độ mọi ca","duration_minutes":40,"result":"Không thực hiện ngay: chẩn đoán đã có dữ kiện phù hợp; đánh giá lại chỉ định theo diễn tiến."}],"choices":{"diagnosis":{"ydx":["Loét tá tràng chưa biến chứng","Viêm bàng quang cấp","Viêm tụy cấp; nghĩ nguyên nhân liên quan rượu","Hội chứng ruột kích thích"]},"actions":["Đánh giá khả năng ăn đường miệng sớm theo dung nạp","Bù dịch đẳng trương có đánh giá lại theo đáp ứng","Giảm đau và theo dõi sinh hiệu, lượng nước tiểu, chức năng thận","Khẳng định mức độ nhẹ ngay khi nhập viện và ngừng theo dõi"]}}'::jsonb,
