values (
  'noi-tieu-hoa-003',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-pancreatitis-acg-2024-60c6b3c22ea7","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38857482/","title":"American College of Gastroenterology Guidelines: Management of Acute Pancreatitis, 2024. https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/","organization":null,"year_version":null,"citation":"American College of Gastroenterology Guidelines: Management of Acute Pancreatitis, 2024. https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm tụy cấp; nghĩ nguyên nhân liên quan rượu","credit":"full"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Viêm bàng quang cấp","credit":"none"},{"text":"Loét tá tràng chưa biến chứng","credit":"none"}]},"action_options":[{"text":"Bù dịch đẳng trương có đánh giá lại theo đáp ứng","time_minutes":2,"grade":"critical","rationale":"Tránh cả thiếu dịch và quá tải."},{"text":"Giảm đau và theo dõi sinh hiệu, lượng nước tiểu, chức năng thận","time_minutes":2,"grade":"critical","rationale":"Phát hiện diễn tiến xấu."},{"text":"Đánh giá khả năng ăn đường miệng sớm theo dung nạp","time_minutes":2,"grade":"recommended","rationale":"Không mặc định nhịn ăn kéo dài."},{"text":"Khẳng định mức độ nhẹ ngay khi nhập viện và ngừng theo dõi","time_minutes":0,"grade":"harmful","rationale":"Phân loại mức độ cần đánh giá suy tạng, biến chứng và diễn tiến."}],"teaching_explanation":"Đau phù hợp và lipase tăng rõ có thể đủ xác định viêm tụy cấp mà chưa cần CT thường quy. Chẩn đoán bệnh, xác định nguyên nhân và đánh giá mức độ nặng là ba nhiệm vụ khác nhau."}'::jsonb,
  '762324c5fef6a3c953216dcccda8fdc949b8f75eaadd437d3ffaa173fb57e9d2'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tieu-hoa-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn máu và phân đen sau dùng thuốc giảm đau","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nữ","patient_label":"Người bệnh mô phỏng N04"},"presentation":{"intro":"Người bệnh đến cấp cứu vì nôn máu, đi phân đen và choáng khi đứng.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":88,"dbp":54,"rr":24,"temperature_c":36.5,"spo2":97},"history":[{"question":"Nôn và phân có đặc điểm gì?","response":"Nôn máu đỏ sẫm hai lần, đi phân đen dính trong một ngày."},{"question":"Có ngất, đau ngực hoặc khó thở không?","response":"Chóng mặt nhiều khi đứng, chưa ngất; không đau ngực."},{"question":"Có dùng NSAID, aspirin hoặc thuốc chống đông không?","response":"Tự dùng diclofenac khoảng 10 ngày vì đau gối; không dùng chống đông."},{"question":"Có tiền sử xơ gan hoặc xuất huyết tiêu hóa không?","response":"Không ghi nhận xơ gan; chưa từng xuất huyết tiêu hóa."},{"question":"Lần ăn uống gần nhất và thời điểm chảy máu?","response":"Ăn lần cuối 6 giờ trước; nôn máu lần đầu 3 giờ trước."},{"question":"Có dị ứng hoặc bệnh tim, thận không?","response":"Không ghi nhận dị ứng; có tăng huyết áp, chưa ghi nhận suy tim hoặc bệnh thận."}],"examination":[{"group":"K","item":"Đường thở và tri giác","finding":"Tỉnh nhưng mệt, hiện tự bảo vệ đường thở; cần đánh giá lại nếu nôn máu tiếp."},{"group":"K","item":"Tuần hoàn","finding":"Da niêm nhợt, chi mát, mạch nhanh, thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Khám bụng","finding":"Đau nhẹ thượng vị, không co cứng hoặc đề kháng."},{"group":"K","item":"Đánh giá phân sau giải thích và đồng thuận","finding":"Phân đen dạng hắc ín."}],"investigations":[{"name":"Công thức máu và theo dõi lại","duration_minutes":10,"result":"Hemoglobin 7,4 g/dL; tiểu cầu 220 G/L."},{"name":"Nhóm máu và xét nghiệm tương hợp","duration_minutes":10,"result":"Đã lấy mẫu, chuẩn bị phương án truyền máu theo tình trạng lâm sàng."},{"name":"Chức năng thận, điện giải và đông máu","duration_minutes":10,"result":"Ure 13 mmol/L; creatinin 96 µmol/L; INR 1,1."},{"name":"Nội soi sau hồi sức ban đầu","duration_minutes":20,"result":"Loét hành tá tràng có mạch máu lộ, không thấy giãn tĩnh mạch thực quản."},{"name":"Xét nghiệm máu ẩn trong phân để xác nhận chảy máu đã rõ","duration_minutes":10,"result":"Không thực hiện: đã có nôn máu và phân đen rõ."}],"choices":{"diagnosis":{"ydx":["Trĩ không biến chứng","Xuất huyết tiêu hóa trên do loét tá tràng, kèm dấu giảm tưới máu","Hội chứng ruột kích thích","Viêm ruột nhiễm khuẩn không biến chứng"]},"actions":["Quyết định truyền máu theo huyết động, mất máu tiếp diễn và bệnh kèm","Tiếp tục diclofenac vì đau gối","Cầm máu nội soi và điều trị sau nội soi theo tổn thương","Thiết lập đường truyền, lấy xét nghiệm và chuẩn bị máu"]}}'::jsonb,
  '26d94d29eb1fcb702c3b8ee64dc004a54a51fd02bbce624a2891011d5594f27a'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
