values (
  'noi-tieu-hoa-004',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-nice-cg141","resource_type":"guideline","source":"https://www.nice.org.uk/guidance/cg141","title":"NICE CG141, Acute upper gastrointestinal bleeding in over 16s: management, 2012, cập nhật 2016. https://www.nice.org.uk/guidance/cg141","organization":null,"year_version":null,"citation":"NICE CG141, Acute upper gastrointestinal bleeding in over 16s: management, 2012, cập nhật 2016. https://www.nice.org.uk/guidance/cg141","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Xuất huyết tiêu hóa trên do loét tá tràng, kèm dấu giảm tưới máu","credit":"full"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Viêm ruột nhiễm khuẩn không biến chứng","credit":"none"},{"text":"Trĩ không biến chứng","credit":"none"}]},"action_options":[{"text":"Thiết lập đường truyền, lấy xét nghiệm và chuẩn bị máu","time_minutes":2,"grade":"critical","rationale":"Điều trị cấp cứu không chờ hoàn tất toàn bộ chẩn đoán."},{"text":"Quyết định truyền máu theo huyết động, mất máu tiếp diễn và bệnh kèm","time_minutes":2,"grade":"critical","rationale":"Không chỉ dựa vào một giá trị hemoglobin."},{"text":"Cầm máu nội soi và điều trị sau nội soi theo tổn thương","time_minutes":2,"grade":"recommended","rationale":"Mạch máu lộ là dấu cần xử trí phù hợp."},{"text":"Tiếp tục diclofenac vì đau gối","time_minutes":0,"grade":"harmful","rationale":"Cần ngừng và rà thuốc làm tăng nguy cơ xuất huyết."}],"teaching_explanation":"SpO2 bình thường không loại trừ giảm tưới máu do mất máu. Phải hồi sức và đánh giá nguy cơ đồng thời với chuẩn bị chẩn đoán, cầm máu."}'::jsonb,
  'a76fab82e84153923489efd044208e484bf458b9eb7ecf32bb9d0dd548c004a8'
)
