insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tieu-hoa-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt và đau bụng ở người bệnh xơ gan có cổ trướng","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":59,"sex":"nam","patient_label":"Người bệnh mô phỏng N05"},"presentation":{"intro":"Người bệnh xơ gan có cổ trướng đến viện vì sốt, đau bụng và lượng nước tiểu giảm.","place":null,"clock":null,"night":false},"vitals":{"hr":110,"sbp":94,"dbp":60,"rr":22,"temperature_c":38.4,"spo2":96},"history":[{"question":"Sốt và đau bụng bắt đầu khi nào?","response":"Sốt một ngày, đau âm ỉ khắp bụng, ăn kém."},{"question":"Có tiểu ít hoặc lú lẫn không?","response":"Tiểu ít hơn thường ngày; gia đình chưa ghi nhận lú lẫn."},{"question":"Xơ gan do nguyên nhân gì, đã có biến chứng nào?","response":"Xơ gan liên quan viêm gan B; có cổ trướng; chưa từng được chẩn đoán nhiễm trùng dịch báng."},{"question":"Đang dùng thuốc gì?","response":"Có thuốc kháng virus và lợi tiểu; cần đối chiếu tên, liều trong đơn."},{"question":"Có nôn máu, phân đen hoặc tiêu chảy không?","response":"Không có các triệu chứng này."},{"question":"Gần đây có nhập viện hoặc dùng kháng sinh không?","response":"Không nhập viện hoặc dùng kháng sinh trong 3 tháng gần đây."},{"question":"Đã tăng cân hoặc bụng to nhanh không?","response":"Bụng to hơn trong một tuần."}],"examination":[{"group":"K","item":"Tri giác và tuần hoàn","finding":"Tỉnh, mệt, chi hơi mát, không dấu thần kinh khu trú."},{"group":"K","item":"Khám bụng","finding":"Bụng báng, đau nhẹ lan tỏa, không co cứng hoặc điểm đau khu trú rõ."},{"group":"K","item":"Dấu bệnh gan","finding":"Củng mạc vàng nhẹ, phù hai cổ chân."},{"group":"K","item":"Tim và phổi","finding":"Tim nhanh đều, phổi chưa có ran."}],"investigations":[{"name":"Chọc dịch báng chẩn đoán: đếm tế bào và cấy","duration_minutes":20,"result":"Bạch cầu đa nhân trung tính 620 tế bào/mm³; cấy đang chờ."},{"name":"Chức năng thận, điện giải và xét nghiệm gan","duration_minutes":10,"result":"Creatinin 142 µmol/L, so với 88 µmol/L một tuần trước; natri 130 mmol/L; bilirubin 62 µmol/L."},{"name":"Cấy máu trước kháng sinh nếu không làm chậm điều trị","duration_minutes":10,"result":"Đã lấy mẫu; kết quả đang chờ."},{"name":"Siêu âm bụng","duration_minutes":15,"result":"Gan hình thái xơ, có dịch báng; chưa ghi nhận bất thường khu trú giải thích đau."},{"name":"Chờ cấy dịch báng dương tính mới điều trị","duration_minutes":10,"result":"Không phù hợp: kết quả tế bào và bệnh cảnh đã đặt ra chỉ định điều trị."}],"choices":{"diagnosis":{"ydx":["Nhiễm trùng dịch báng tự phát trên nền xơ gan; kèm tổn thương thận cấp cần đánh giá","Cổ trướng ổn định không có biến chứng","Viêm dạ dày đơn thuần","Hội chứng ruột kích thích"]},"actions":["Khởi trị kháng sinh theo bối cảnh nhiễm trùng và dữ liệu kháng thuốc địa phương","Rà lợi tiểu, thuốc ảnh hưởng thận và nguyên nhân tổn thương thận cấp","Đánh giá sử dụng albumin theo hướng dẫn và nguy cơ thận","Tự tăng lợi tiểu trong khi huyết áp thấp và chức năng thận xấu đi"]}}'::jsonb,
  '1193d800194c6d3caf1976f3260be8787a281f8bfdaaecec1f94d61dbe9407ab'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
