values (
  'noi-tieu-hoa-005',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ascites-aasld-2021","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/33942342/","title":"AASLD Practice Guidance: Diagnosis, Evaluation, and Management of Ascites, Spontaneous Bacterial Peritonitis and Hepatorenal Syndrome, 2021. DOI: 10.1002/hep.31884. https://onlinelibrary.wiley.com/doi/full/10.1002/hep.31884","organization":null,"year_version":null,"citation":"AASLD Practice Guidance: Diagnosis, Evaluation, and Management of Ascites, Spontaneous Bacterial Peritonitis and Hepatorenal Syndrome, 2021. DOI: 10.1002/hep.31884. https://onlinelibrary.wiley.com/doi/full/10.1002/hep.31884","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhiễm trùng dịch báng tự phát trên nền xơ gan; kèm tổn thương thận cấp cần đánh giá","credit":"full"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Viêm dạ dày đơn thuần","credit":"none"},{"text":"Cổ trướng ổn định không có biến chứng","credit":"none"}]},"action_options":[{"text":"Khởi trị kháng sinh theo bối cảnh nhiễm trùng và dữ liệu kháng thuốc địa phương","time_minutes":2,"grade":"critical","rationale":"Không chờ cấy khi đã có chỉ định."},{"text":"Đánh giá sử dụng albumin theo hướng dẫn và nguy cơ thận","time_minutes":2,"grade":"critical","rationale":"Cần phối hợp theo dõi đáp ứng và nguy cơ quá tải."},{"text":"Rà lợi tiểu, thuốc ảnh hưởng thận và nguyên nhân tổn thương thận cấp","time_minutes":2,"grade":"recommended","rationale":"Không mặc định mọi tăng creatinin là hội chứng gan–thận."},{"text":"Tự tăng lợi tiểu trong khi huyết áp thấp và chức năng thận xấu đi","time_minutes":0,"grade":"harmful","rationale":"Có thể làm giảm thể tích tuần hoàn hiệu dụng."}],"teaching_explanation":"Ở người bệnh xơ gan có cổ trướng, sốt hoặc suy thận cần nghĩ đến nhiễm trùng dịch báng. Tổn thương thận phải được đánh giá nguyên nhân trước khi kết luận hội chứng gan–thận."}'::jsonb,
  '2a5cbd98f974eda64ee0ba12aa97e8dc494994650a97f7d116bc094ae4f083f8'
)
