insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tieu-hoa-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nóng rát sau xương ức và ợ chua sau ăn","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":29,"sex":"nữ","patient_label":"Người bệnh mô phỏng N06"},"presentation":{"intro":"Người bệnh đến phòng khám vì nóng rát sau xương ức và ợ chua trong 3 tháng.","place":null,"clock":null,"night":false},"vitals":{"hr":78,"sbp":116,"dbp":74,"rr":16,"temperature_c":36.6,"spo2":99},"history":[{"question":"Cảm giác nóng rát xuất hiện khi nào?","response":"Thường sau bữa ăn lớn hoặc khi nằm ngay sau ăn, khoảng 4 ngày mỗi tuần."},{"question":"Có dịch chua trào lên miệng không?","response":"Có vị chua trào lên họng, nhất là buổi tối."},{"question":"Có nuốt nghẹn, nuốt đau hoặc sụt cân không?","response":"Không có; cân nặng ổn định."},{"question":"Có nôn máu, phân đen hoặc nôn kéo dài không?","response":"Không có."},{"question":"Đau có liên quan gắng sức, lan tay hoặc kèm khó thở không?","response":"Không liên quan gắng sức, không lan tay, không khó thở hoặc ngất."},{"question":"Có khả năng mang thai hoặc đang dùng thuốc gì không?","response":"Không mang thai, không dùng thuốc thường xuyên."},{"question":"Thói quen ăn uống và giờ ngủ thế nào?","response":"Thường ăn tối muộn, uống cà phê và nằm trong vòng 30 phút sau ăn."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, không xanh xao, không dấu mất nước."},{"group":"K","item":"Tim và phổi","finding":"Tim đều, không âm thổi; phổi không ran."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không điểm đau khu trú, không phản ứng phúc mạc."},{"group":"K","item":"Thể trạng","finding":"BMI 27,0 kg/m², số liệu giả định phục vụ đánh giá yếu tố liên quan."}],"investigations":[{"name":"Nội soi tiêu hóa trên thường quy ngay trong lần khám đầu","duration_minutes":20,"result":"Chưa thực hiện: chưa có dấu báo động hoặc thất bại điều trị ban đầu."},{"name":"Đo pH hoặc pH-trở kháng thực quản thường quy ngay","duration_minutes":30,"result":"Chưa thực hiện: dành cho tình huống có chỉ định chuyên khoa, không bắt buộc trong đánh giá ban đầu này."},{"name":"Công thức máu","duration_minutes":10,"result":"Hemoglobin 13,4 g/dL, không thiếu máu; xét nghiệm có sẵn từ lần khám gần đây."},{"name":"CT bụng để xác nhận trào ngược","duration_minutes":40,"result":"Không thực hiện: không phù hợp mục tiêu chẩn đoán trong ca này."}],"choices":{"diagnosis":{"ydx":["Viêm túi mật cấp","Bệnh trào ngược dạ dày–thực quản, chẩn đoán lâm sàng ban đầu","Tắc ruột cơ học","Viêm tụy cấp"]},"actions":["Dùng PPI vô thời hạn mà không đánh giá lại","Tránh nằm ngay sau ăn và điều chỉnh bữa tối","Cân nhắc PPI thử trong thời gian phù hợp và hẹn đánh giá lại","Hướng dẫn giảm cân phù hợp và nhận diện yếu tố kích phát cá nhân"]}}'::jsonb,
  '3383257e38eb80198cc2c8af5bcba1673e4bc73b1a32b33b4604e449904155c3'
)
