  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tiêu chảy sau một đợt dùng kháng sinh","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nam","patient_label":"Người bệnh mô phỏng N07"},"presentation":{"intro":"Người bệnh nhập khoa Nội vì tiêu chảy nhiều lần sau điều trị nhiễm khuẩn hô hấp bằng kháng sinh.","place":null,"clock":null,"night":false},"vitals":{"hr":96,"sbp":112,"dbp":70,"rr":18,"temperature_c":37.8,"spo2":97},"history":[{"question":"Đi tiêu bao nhiêu lần, phân có đặc điểm gì?","response":"Phân nước 7 lần/ngày trong 3 ngày, không thấy máu."},{"question":"Gần đây dùng kháng sinh hoặc nhập viện không?","response":"Vừa dùng amoxicillin–clavulanate 7 ngày; kết thúc 5 ngày trước."},{"question":"Có dùng thuốc nhuận tràng không?","response":"Không dùng."},{"question":"Có đau bụng, nôn hoặc bụng chướng tăng không?","response":"Đau quặn nhẹ lan tỏa, không nôn, chưa chướng tăng."},{"question":"Uống nước và lượng nước tiểu thế nào?","response":"Uống kém, tiểu ít hơn thường ngày."},{"question":"Đã từng nhiễm C. difficile hoặc suy giảm miễn dịch chưa?","response":"Chưa ghi nhận."},{"question":"Có người cùng ăn bị tiêu chảy không?","response":"Không ghi nhận."}],"examination":[{"group":"K","item":"Toàn trạng và nước","finding":"Tỉnh, niêm hơi khô, chưa có dấu giảm tưới máu nặng."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, đau nhẹ lan tỏa, không co cứng hoặc chướng rõ."},{"group":"K","item":"Đánh giá biến chứng","finding":"Chưa có tụt huyết áp, liệt ruột hoặc dấu phúc mạc."},{"group":"K","item":"Tim và phổi","finding":"Tim đều, phổi không ran."}],"investigations":[{"name":"Xét nghiệm C. difficile trên mẫu phân lỏng theo thuật toán cơ sở","duration_minutes":10,"result":"GDH dương tính và độc tố A/B dương tính."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 12,8 G/L; hemoglobin 12,7 g/dL."},{"name":"Chức năng thận và điện giải","duration_minutes":10,"result":"Creatinin 108 µmol/L; kali 3,2 mmol/L."},{"name":"Xét nghiệm C. difficile lại để chứng minh khỏi sau khi hết tiêu chảy","duration_minutes":10,"result":"Không thực hiện thường quy: không dùng xét nghiệm kiểm tra khỏi ở người đã hết triệu chứng."}],"choices":{"diagnosis":{"ydx":["Hội chứng ruột kích thích","Mang C. difficile không triệu chứng","Nhiễm Clostridioides difficile có triệu chứng, đợt đầu","Tắc ruột cơ học"]},"actions":["Áp dụng phòng ngừa tiếp xúc, vệ sinh tay và môi trường theo quy trình","Làm xét nghiệm kiểm tra khỏi thường quy khi đã hết triệu chứng","Rà và ngừng kháng sinh không còn cần thiết","Bù nước, điều chỉnh điện giải và theo dõi diễn tiến"]}}'::jsonb,
  '50970da1f57acae987ed78d8f19ed34bfb21abf89d7cdc23575fa8c7fd74650d'
)
