values (
  'noi-tieu-hoa-008',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-008","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Mệt kéo dài ở người đã biết nhiễm viêm gan B","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":43,"sex":"nam","patient_label":"Người bệnh mô phỏng N08"},"presentation":{"intro":"Người bệnh đến khám vì mệt kéo dài, có hồ sơ HBsAg dương tính từ hai năm trước nhưng chưa theo dõi đều.","place":null,"clock":null,"night":false},"vitals":{"hr":82,"sbp":120,"dbp":76,"rr":17,"temperature_c":36.7,"spo2":98},"history":[{"question":"HBsAg được phát hiện khi nào và có hồ sơ không?","response":"Có kết quả dương tính hai năm trước và một năm trước."},{"question":"Đã dùng thuốc kháng virus hoặc tự ngừng thuốc chưa?","response":"Chưa dùng thuốc kháng virus."},{"question":"Có vàng da, bụng to, phù chân hoặc xuất huyết không?","response":"Không ghi nhận."},{"question":"Có uống rượu hoặc dùng thuốc, thực phẩm bổ sung không rõ thành phần không?","response":"Ít uống rượu, không dùng sản phẩm không rõ thành phần."},{"question":"Gia đình có xơ gan hoặc ung thư gan không?","response":"Cha từng được điều trị ung thư gan."},{"question":"Người sống cùng đã xét nghiệm và tiêm vaccine chưa?","response":"Vợ chưa rõ tình trạng xét nghiệm và tiêm vaccine."},{"question":"Có đau bụng liên tục hoặc sụt cân không?","response":"Không đau bụng liên tục, cân nặng ổn định."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, không vàng da rõ, không dấu mất nước."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không dấu cổ trướng, không sờ thấy khối."},{"group":"K","item":"Dấu mất bù","finding":"Không phù chân, không rối loạn tri giác hoặc dấu xuất huyết."},{"group":"K","item":"Tim và phổi","finding":"Không ghi nhận bất thường."}],"investigations":[{"name":"HBsAg, HBeAg và HBV DNA","duration_minutes":10,"result":"HBsAg dương tính; HBeAg âm tính; HBV DNA 180.000 IU/mL."},{"name":"Men gan, bilirubin, albumin và INR","duration_minutes":10,"result":"ALT 126 U/L, lần trước 118 U/L; AST 82 U/L; bilirubin 17 µmol/L; albumin 41 g/L; INR 1,0."},{"name":"Chức năng thận và đánh giá đồng nhiễm","duration_minutes":10,"result":"Creatinin 86 µmol/L; HIV, anti-HCV và anti-HDV âm tính."},{"name":"Siêu âm gan và đánh giá xơ hóa theo quy trình","duration_minutes":15,"result":"Không có tổn thương khu trú hoặc cổ trướng; mức xơ hóa cần hoàn tất đánh giá chuyên khoa."},{"name":"CT gan lặp hằng tháng khi không có dấu nghi ngờ","duration_minutes":40,"result":"Không thực hiện: không phải chiến lược theo dõi thường quy phù hợp."}],"choices":{"diagnosis":{"ydx":["Xơ gan mất bù đã xác định","Ung thư gan đã xác định chỉ từ tiền sử gia đình","Viêm gan B mạn có hoạt động, cần đánh giá điều trị và xơ hóa","Viêm gan B cấp chỉ dựa vào HBsAg hiện tại"]},"actions":["Lập kế hoạch theo dõi ung thư gan theo mức nguy cơ","Tư vấn đường lây, xét nghiệm và vaccine cho người tiếp xúc","Đánh giá xơ hóa và chỉ định kháng virus","Khẳng định HBeAg âm tính nghĩa là virus không hoạt động"]}}'::jsonb,
  'bc19cd41756b53e3f8b8608cb85fee5058dc30598a93dbb2acb89d28f72813d9'
