  'noi-tieu-hoa-008',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-008","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-who-hbv-2024","resource_type":"guideline","source":"https://who.int/publications/i/item/9789240090903","title":"WHO, Guidelines for the prevention, diagnosis, care and treatment for people with chronic hepatitis B infection, 2024. https://www.who.int/publications/i/item/9789240090903","organization":null,"year_version":null,"citation":"WHO, Guidelines for the prevention, diagnosis, care and treatment for people with chronic hepatitis B infection, 2024. https://www.who.int/publications/i/item/9789240090903","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm gan B mạn có hoạt động, cần đánh giá điều trị và xơ hóa","credit":"full"},{"text":"Viêm gan B cấp chỉ dựa vào HBsAg hiện tại","credit":"none"},{"text":"Xơ gan mất bù đã xác định","credit":"none"},{"text":"Ung thư gan đã xác định chỉ từ tiền sử gia đình","credit":"none"}]},"action_options":[{"text":"Đánh giá xơ hóa và chỉ định kháng virus","time_minutes":2,"grade":"recommended","rationale":"Không suy ra mức xơ hóa chỉ từ ALT."},{"text":"Lập kế hoạch theo dõi ung thư gan theo mức nguy cơ","time_minutes":2,"grade":"recommended","rationale":"Tiền sử gia đình cần được đưa vào đánh giá."},{"text":"Tư vấn đường lây, xét nghiệm và vaccine cho người tiếp xúc","time_minutes":2,"grade":"recommended","rationale":"Giảm lây truyền mà không kỳ thị."},{"text":"Khẳng định HBeAg âm tính nghĩa là virus không hoạt động","time_minutes":0,"grade":"harmful","rationale":"Cần kết hợp HBV DNA và tổn thương gan."}],"teaching_explanation":"HBsAg tồn tại kéo dài giúp xác định nhiễm mạn, nhưng đánh giá hoạt động và điều trị cần thêm dữ kiện. Men gan, tải lượng virus, xơ hóa và nguy cơ ung thư gan có vai trò khác nhau."}'::jsonb,
