insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tieu-hoa-009',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-009","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tiêu chảy máu và mót rặn kéo dài","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":32,"sex":"nữ","patient_label":"Người bệnh mô phỏng N09"},"presentation":{"intro":"Người bệnh khám chuyên khoa Tiêu hóa vì tiêu chảy có máu và mót rặn trong 6 tuần.","place":null,"clock":null,"night":false},"vitals":{"hr":84,"sbp":110,"dbp":72,"rr":18,"temperature_c":36.8,"spo2":99},"history":[{"question":"Đi tiêu bao nhiêu lần và máu xuất hiện thế nào?","response":"Khoảng 4 lần/ngày, phân mềm có máu và nhầy."},{"question":"Có mót rặn hoặc phải đi tiêu ban đêm không?","response":"Có mót rặn; đôi khi thức giấc để đi tiêu."},{"question":"Có sốt, sụt cân hoặc đau bụng tăng không?","response":"Sụt khoảng 2 kg trong 6 tuần; đau bụng dưới nhẹ; không sốt."},{"question":"Có dùng kháng sinh, đi xa hoặc người cùng ăn mắc bệnh không?","response":"Không dùng kháng sinh gần đây, không đi xa hoặc có người cùng ăn mắc bệnh."},{"question":"Có đau khớp, mắt đỏ đau hoặc tổn thương da không?","response":"Chưa ghi nhận."},{"question":"Có dùng NSAID hoặc từng mắc bệnh tương tự không?","response":"Không dùng NSAID; đây là đợt đầu."},{"question":"Gia đình có bệnh viêm ruột không?","response":"Không ghi nhận."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, hơi nhợt, không mất nước rõ."},{"group":"K","item":"Khám bụng","finding":"Đau nhẹ bụng dưới trái, bụng không chướng hoặc có dấu phúc mạc."},{"group":"K","item":"Đánh giá mắt, da và khớp","finding":"Chưa ghi nhận biểu hiện ngoài ruột."},{"group":"K","item":"Khám vùng hậu môn khi phù hợp và có đồng thuận","finding":"Không thấy tổn thương quanh hậu môn rõ hoặc trĩ giải thích toàn bộ bệnh cảnh."}],"investigations":[{"name":"Công thức máu, CRP và albumin","duration_minutes":10,"result":"Hemoglobin 11,4 g/dL; CRP 12 mg/L; albumin 38 g/L."},{"name":"Xét nghiệm phân tìm nguyên nhân nhiễm trùng","duration_minutes":10,"result":"Không phát hiện tác nhân gây bệnh trong bộ xét nghiệm của cơ sở; C. difficile âm tính."},{"name":"Nội soi đại tràng và sinh thiết sau đánh giá an toàn","duration_minutes":20,"result":"Viêm liên tục từ trực tràng đến đại tràng xuống; sinh thiết gợi ý viêm đại tràng mạn hoạt động với biến dạng cấu trúc tuyến."},{"name":"Calprotectin phân","duration_minutes":10,"result":"620 µg/g; tăng theo ngưỡng của phòng xét nghiệm."},{"name":"Xét nghiệm máu ẩn trong phân khi đã thấy máu rõ","duration_minutes":10,"result":"Không thực hiện: không giải quyết câu hỏi chẩn đoán hiện tại."}],"choices":{"diagnosis":{"ydx":["Viêm loét đại tràng, tổn thương đại tràng trái","Hội chứng ruột kích thích","Trĩ đơn thuần","Viêm tụy cấp"]},"actions":["Đặt mục tiêu cải thiện triệu chứng và kiểm soát viêm","Cân nhắc phối hợp 5-ASA đường uống và trực tràng theo chuyên khoa","Phân mức hoạt động và rà nguy cơ cần nhập viện","Dùng corticoid lâu dài để duy trì lui bệnh"]}}'::jsonb,
  'ae16c66feebe1dc8e8747c50d3c4ad9cd15037ae41b8f3cd0cf46cb9ddf95c9a'
)
