values (
  'noi-tieu-hoa-009',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-009","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tieu-hoa-009-1","resource_type":"other","source":"ACG Clinical Guideline Update: Ulcerative Colitis in Adults, 2025; bản tóm lược chính thức của ACG. https://gi.org/journals-publications/ebgi/alkazzi_aug2025/","title":"ACG Clinical Guideline Update: Ulcerative Colitis in Adults, 2025; bản tóm lược chính thức của ACG. https://gi.org/journals-publications/ebgi/alkazzi_aug2025/","organization":null,"year_version":null,"citation":"ACG Clinical Guideline Update: Ulcerative Colitis in Adults, 2025; bản tóm lược chính thức của ACG. https://gi.org/journals-publications/ebgi/alkazzi_aug2025/","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm loét đại tràng, tổn thương đại tràng trái","credit":"full"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Trĩ đơn thuần","credit":"none"},{"text":"Viêm tụy cấp","credit":"none"}]},"action_options":[{"text":"Phân mức hoạt động và rà nguy cơ cần nhập viện","time_minutes":2,"grade":"recommended","rationale":"Quyết định điều trị không chỉ dựa vào phạm vi nội soi."},{"text":"Cân nhắc phối hợp 5-ASA đường uống và trực tràng theo chuyên khoa","time_minutes":2,"grade":"recommended","rationale":"Phù hợp một số bệnh cảnh đại tràng trái nhẹ đến vừa."},{"text":"Đặt mục tiêu cải thiện triệu chứng và kiểm soát viêm","time_minutes":2,"grade":"recommended","rationale":"Hết triệu chứng không luôn đồng nghĩa hết hoạt động bệnh."},{"text":"Dùng corticoid lâu dài để duy trì lui bệnh","time_minutes":0,"grade":"harmful","rationale":"Cần chiến lược duy trì không phụ thuộc corticoid."}],"teaching_explanation":"Tiêu chảy máu, mót rặn và triệu chứng ban đêm không phù hợp với IBS đơn thuần. Chẩn đoán bệnh viêm ruột cần tổng hợp dữ kiện và đánh giá nguyên nhân nhiễm trùng."}'::jsonb,
  '470662d5209206de942d70278a46584c6bb207c96cf7081b941f40e8d5b130d7'
)
