insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tieu-hoa-010',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-010","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt rét run, vàng da và đau hạ sườn phải","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":76,"sex":"nữ","patient_label":"Người bệnh mô phỏng N10"},"presentation":{"intro":"Người bệnh đến cấp cứu vì sốt rét run, vàng da và đau hạ sườn phải, cần phối hợp Nội Tiêu hóa, hồi sức và đội can thiệp đường mật.","place":null,"clock":null,"night":false},"vitals":{"hr":116,"sbp":86,"dbp":50,"rr":26,"temperature_c":39.2,"spo2":95},"history":[{"question":"Đau và sốt xuất hiện thế nào?","response":"Đau hạ sườn phải hai ngày; sốt rét run từ hôm qua."},{"question":"Vàng da, nước tiểu hoặc màu phân thay đổi không?","response":"Vàng mắt tăng, nước tiểu sẫm, phân nhạt hơn thường ngày."},{"question":"Có lú lẫn, ngất hoặc tiểu ít không?","response":"Tiểu ít; gia đình thấy trả lời chậm hơn thường ngày."},{"question":"Có tiền sử sỏi hoặc can thiệp đường mật không?","response":"Từng phát hiện sỏi túi mật; chưa can thiệp đường mật."},{"question":"Có dùng chống đông, dị ứng hoặc bệnh tim, thận không?","response":"Không dùng chống đông, chưa ghi nhận dị ứng; có tăng huyết áp."},{"question":"Gần đây có nhập viện hoặc dùng kháng sinh không?","response":"Không trong ba tháng gần đây."},{"question":"Có nôn máu hoặc đi phân đen không?","response":"Không có."}],"examination":[{"group":"K","item":"Tri giác và tưới máu","finding":"Trả lời chậm, chi mát, thời gian làm đầy mao mạch 4 giây."},{"group":"K","item":"Da và mắt","finding":"Vàng da, vàng củng mạc."},{"group":"K","item":"Khám bụng","finding":"Đau hạ sườn phải, không co cứng lan tỏa."},{"group":"K","item":"Tim và phổi","finding":"Tim nhanh đều; thở nhanh, chưa có ran rõ."}],"investigations":[{"name":"Công thức máu, CRP, lactate và xét nghiệm chức năng cơ quan","duration_minutes":10,"result":"Bạch cầu 19,2 G/L; CRP 180 mg/L; lactate 3,8 mmol/L; creatinin 176 µmol/L; tiểu cầu 145 G/L."},{"name":"Xét nghiệm gan mật và đông máu","duration_minutes":10,"result":"Bilirubin toàn phần 118 µmol/L, trực tiếp 86 µmol/L; ALP và GGT tăng; INR 1,3."},{"name":"Cấy máu trước kháng sinh nếu không làm chậm điều trị","duration_minutes":10,"result":"Đã lấy hai bộ cấy; kết quả đang chờ."},{"name":"Siêu âm đường mật","duration_minutes":15,"result":"Ống mật chủ giãn 12 mm, có hình ảnh sỏi khoảng 9 mm."},{"name":"MRCP bắt buộc trước mọi quyết định dẫn lưu dù người bệnh không ổn","duration_minutes":40,"result":"Không ưu tiên nếu làm chậm kiểm soát nguồn nhiễm đã có bằng chứng rõ."}],"choices":{"diagnosis":{"ydx":["Viêm túi mật đơn thuần đã giải thích đầy đủ mọi dấu hiệu","Viêm đường mật cấp do sỏi ống mật chủ, có dấu suy cơ quan và bất ổn tuần hoàn","Hội chứng ruột kích thích","Viêm gan B mạn ổn định"]},"actions":["Đánh giá ABC, hồi sức theo đáp ứng và huy động đội hồi sức","Trì hoãn can thiệp nhiều ngày để chờ bilirubin tự giảm","Hội chẩn can thiệp dẫn lưu đường mật khẩn","Khởi kháng sinh sớm, hiệu chỉnh theo chức năng thận và dữ liệu kháng thuốc"]}}'::jsonb,
  'ae31d6bf1f0a0f7be40919a45631b301a85e5a08f00ab96b12134f8393961c86'
)
