ssion_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm đường mật cấp do sỏi ống mật chủ, có dấu suy cơ quan và bất ổn tuần hoàn","credit":"full"},{"text":"Viêm túi mật đơn thuần đã giải thích đầy đủ mọi dấu hiệu","credit":"none"},{"text":"Viêm gan B mạn ổn định","credit":"none"},{"text":"Hội chứng ruột kích thích","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, hồi sức theo đáp ứng và huy động đội hồi sức","time_minutes":2,"grade":"critical","rationale":"Người bệnh có dấu giảm tưới máu và rối loạn tri giác."},{"text":"Khởi kháng sinh sớm, hiệu chỉnh theo chức năng thận và dữ liệu kháng thuốc","time_minutes":2,"grade":"critical","rationale":"Không chờ kết quả cấy khi đang diễn tiến nặng."},{"text":"Hội chẩn can thiệp dẫn lưu đường mật khẩn","time_minutes":2,"grade":"recommended","rationale":"Điều trị cần kiểm soát nguồn nhiễm bên cạnh kháng sinh."},{"text":"Trì hoãn can thiệp nhiều ngày để chờ bilirubin tự giảm","time_minutes":0,"grade":"harmful","rationale":"Tắc nghẽn nhiễm trùng có thể tiếp tục gây suy cơ quan."}],"teaching_explanation":"Sốt, ứ mật và bằng chứng tắc đường mật giúp định hướng viêm đường mật. Tụt huyết áp hoặc rối loạn tri giác đòi hỏi xử trí khẩn, không chỉ làm thêm xét nghiệm."}'::jsonb,
