  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau ngực dữ dội 2 giờ, điện tim ST chênh lên vùng trước","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông N. V. T. (mô phỏng)"},"presentation":{"intro":"Ông được đưa đến cấp cứu vì đau thắt ngực dữ dội 2 giờ, vã mồ hôi, không đỡ khi nghỉ.","place":null,"clock":null,"night":false},"vitals":{"hr":92,"sbp":138,"dbp":86,"rr":20,"temperature_c":36.8,"spo2":96},"history":[{"question":"Đau ngực bắt đầu lúc nào, đau thế nào, lan đi đâu?","response":"Đau thắt như bị đè nặng sau xương ức, bắt đầu cách đây 2 giờ khi đang nghỉ, lan lên cổ và cánh tay trái, kéo dài liên tục."},{"question":"Cơn đau có đỡ khi nghỉ hoặc ngậm nitroglycerin không?","response":"Nghỉ không đỡ; vợ cho ngậm một viên nitroglycerin dưới lưỡi, đau chỉ giảm nhẹ rồi lại tăng."},{"question":"Có vã mồ hôi, buồn nôn, khó thở, ngất không?","response":"Vã mồ hôi lạnh, buồn nôn, hơi khó thở; không ngất."},{"question":"Tiền sử tăng huyết áp, đái tháo đường, rối loạn lipid, hút thuốc?","response":"Tăng huyết áp 8 năm điều trị không đều; rối loạn lipid chưa dùng statin; hút khoảng 20 gói-năm, còn hút."},{"question":"Trước đây có từng đau ngực khi gắng sức không?","response":"Hai tháng nay đôi khi tức ngực khi leo cầu thang, nghỉ vài phút hết."},{"question":"Có đau xé ra sau lưng, chấn thương ngực, hoặc dùng chống đông, phẫu thuật gần đây không (chống chỉ định tiêu sợi huyết)?","response":"Không đau xé ra lưng; không chấn thương, không mổ, không xuất huyết, không đột quỵ trước đây; không dùng chống đông."},{"question":"Gia đình có ai bệnh mạch vành sớm không?","response":"Cha mất đột ngột năm 55 tuổi, nghi bệnh tim."},{"question":"Nghề nghiệp, chế độ ăn?","response":"Chủ cửa hàng, ăn mặn và nhiều mỡ, ít vận động."}],"examination":[{"group":"K","item":"Tim","finding":"Nhịp đều, tần số 92 lần/phút, T1 T2 rõ, không có tiếng thổi, không T3."},{"group":"K","item":"Phổi","finding":"Rì rào phế nang rõ, không ran (Killip I)."},{"group":"K","item":"Tuần hoàn ngoại vi và tĩnh mạch cổ","finding":"Da ẩm lạnh nhẹ, tĩnh mạch cổ không nổi, không phù chân, mạch quay hai bên đều."},{"group":"K","item":"Huyết áp hai tay","finding":"Hai tay chênh dưới 10 mmHg."},{"group":"K","item":"Bụng","finding":"Mềm, không điểm đau khu trú."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo (trong 10 phút đầu)","duration_minutes":10,"result":"Nhịp xoang 92 l/p; ST chênh lên 3–4 mm ở V1–V4, chênh lên ở I và aVL, ST chênh xuống soi gương ở DII, DIII, aVF."},{"name":"Troponin T hoặc I siêu nhạy","duration_minutes":10,"result":"hs-cTnI 420 ng/L (tham chiếu dưới 34 ng/L); không được chờ kết quả để quyết định tái tưới máu."},{"name":"Công thức máu, đường huyết, creatinin, điện giải, lipid, đông máu","duration_minutes":10,"result":"Bạch cầu 11,2 G/L, Hb 146 g/L, tiểu cầu 238 G/L; glucose 7,4 mmol/L; creatinin 92 µmol/L; K 4,1 mmol/L; LDL-C 4,0 mmol/L; INR 1,0."},{"name":"Siêu âm tim tại giường","duration_minutes":15,"result":"Giảm động vùng mỏm và thành trước vách, EF ước tính 45%, không tràn dịch màng tim, không hở van nặng."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Bóng tim không to, phổi sáng, không xung huyết."},{"name":"CT mạch máu toàn bộ để loại trừ bóc tách trước khi quyết định can thiệp","duration_minutes":40,"result":"Không có chỉ định khi điện tim điển hình và không có dấu hiệu bóc tách; làm chậm tái tưới máu."}],"choices":{"diagnosis":{"ydx":["Hội chứng vành cấp không ST chênh","Nhồi máu cơ tim cấp ST chênh lên thành trước, Killip I","Viêm màng ngoài tim cấp","Bóc tách động mạch chủ ngực"]},"actions":["Morphin tĩnh mạch ngay khi vừa thấy đau nhẹ","Tiêm bắp thuốc giảm đau và dùng thuốc chống đông đường tiêm bắp","Atorvastatin 80 mg và dặn giữ yên giường","Cho ra về theo dõi vì troponin chưa có kết quả","Aspirin nhai 300 mg, ticagrelor 180 mg và heparin không phân đoạn theo cân nặng","Kích hoạt đội can thiệp tim mạch, chuyển phòng thông tim","Ghi điện tim 12 chuyển đạo trong 10 phút, gắn monitor và đường truyền tĩnh mạch"]}}'::jsonb,
  '610b5f0df2727c589628624941f0689b196a30c8360de362345732e264161a06'
)
on conflict (case_id) do update set
