insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-tim-mach-001',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-001-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị nhồi máu cơ tim cấp có ST chênh lên, Bộ Y tế Việt Nam, 2022.","title":"Hướng dẫn chẩn đoán và điều trị nhồi máu cơ tim cấp có ST chênh lên, Bộ Y tế Việt Nam, 2022.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị nhồi máu cơ tim cấp có ST chênh lên, Bộ Y tế Việt Nam, 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-acs-esc-2023-0bce3c0fff0f","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/37622654/","title":"2023 ESC Guidelines for the management of acute coronary syndromes, Eur Heart J 2023.","organization":null,"year_version":null,"citation":"2023 ESC Guidelines for the management of acute coronary syndromes, Eur Heart J 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-001-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh mạch vành.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh mạch vành.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh mạch vành.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhồi máu cơ tim cấp ST chênh lên thành trước, Killip I","credit":"full"},{"text":"Hội chứng vành cấp không ST chênh","credit":"none"},{"text":"Bóc tách động mạch chủ ngực","credit":"none"},{"text":"Viêm màng ngoài tim cấp","credit":"none"}]},"action_options":[{"text":"Ghi điện tim 12 chuyển đạo trong 10 phút, gắn monitor và đường truyền tĩnh mạch","time_minutes":2,"grade":"critical","rationale":"Chẩn đoán STEMI dựa vào điện tim; mọi quyết định sau đó phụ thuộc thời gian."},{"text":"Aspirin nhai 300 mg, ticagrelor 180 mg và heparin không phân đoạn theo cân nặng","time_minutes":2,"grade":"critical","rationale":"Điều trị chống huyết khối kép ngay trước can thiệp."},{"text":"Kích hoạt đội can thiệp tim mạch, chuyển phòng thông tim","time_minutes":2,"grade":"critical","rationale":"Thời gian từ chẩn đoán đến luồn dây càng ngắn càng tốt: mục tiêu trong 60 phút nếu đến thẳng cơ sở có can thiệp, tối đa 120 phút nếu chuyển viện (ESC 2023); thời gian này quyết định lượng cơ tim cứu được."},{"text":"Atorvastatin 80 mg và dặn giữ yên giường","time_minutes":2,"grade":"critical","rationale":"Statin liều cao sớm làm giảm biến cố; huyết động ổn định, chưa có suy tim nên có thể cân nhắc chẹn beta liều thấp đường uống."},{"text":"Morphin tĩnh mạch ngay khi vừa thấy đau nhẹ","time_minutes":1,"grade":"waste","rationale":"Chỉ dùng khi đau không kiểm soát; morphin có thể làm chậm hấp thu thuốc kháng tiểu cầu."},{"text":"Cho ra về theo dõi vì troponin chưa có kết quả","time_minutes":0,"grade":"harmful","rationale":"Điện tim STEMI điển hình là chẩn đoán đủ để cấp cứu tái tưới máu, trì hoãn gây tử vong."},{"text":"Tiêm bắp thuốc giảm đau và dùng thuốc chống đông đường tiêm bắp","time_minutes":0,"grade":"harmful","rationale":"Tiêm bắp làm tăng nguy cơ tụ máu và làm sai lệch men tim, không có chỉ định."}],"teaching_explanation":"ST chênh lên kèm đau ngực điển hình đủ để chẩn đoán STEMI và mở động mạch thủ phạm càng sớm càng tốt; không chờ troponin. Điều trị bao gồm chống kết tập tiểu cầu kép, chống đông và tái tưới máu, oxy chỉ khi giảm oxy máu."}'::jsonb,
  '23b89398f74bd85b326d8debf914a2a00cc96c3a9653d7576e128574a9d0df29'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau ngực khi nghỉ, ST chênh xuống và troponin tăng ở người đái tháo đường","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":67,"sex":"nữ","patient_label":"Bà L. T. M. (mô phỏng)"},"presentation":{"intro":"Bà nhập khoa Tim mạch vì đau tức ngực hai lần trong ngày, mỗi lần khoảng 20 phút.","place":null,"clock":null,"night":false},"vitals":{"hr":84,"sbp":150,"dbp":84,"rr":18,"temperature_c":37,"spo2":97},"history":[{"question":"Cơn đau ngực xảy ra khi nào, kéo dài bao lâu?","response":"Hai cơn trong hôm nay, đang ngồi nghỉ, mỗi cơn 20 phút, đau tức giữa ngực lan lên hàm; cơn thứ hai mới hết cách đây 1 giờ."},{"question":"Trước đó có đau ngực khi gắng sức không?","response":"Hai tuần nay đi bộ 200 m đã tức ngực, nghỉ 5 phút hết, tần suất tăng dần."},{"question":"Có khó thở, vã mồ hôi, hồi hộp, ngất không?","response":"Hơi khó thở và vã mồ hôi trong cơn; không hồi hộp, không ngất."},{"question":"Bệnh nền nào đang điều trị?","response":"Đái tháo đường típ 2 mười hai năm dùng metformin; tăng huyết áp mười năm; rối loạn lipid chưa dùng statin đều."},{"question":"Đang dùng thuốc nào, có dị ứng aspirin hoặc từng xuất huyết tiêu hóa không?","response":"Amlodipin 5 mg và metformin; không dị ứng aspirin, chưa từng xuất huyết tiêu hóa."},{"question":"Có đau ngực tăng khi hít sâu hoặc đổi tư thế, có sốt không?","response":"Không đổi theo hơi thở hay tư thế; không sốt."},{"question":"Hút thuốc, uống rượu?","response":"Không hút thuốc, không uống rượu."}],"examination":[{"group":"K","item":"Tim và phổi","finding":"Tim đều 84 l/p, không tiếng thổi; phổi không ran."},{"group":"K","item":"Huyết áp, tuần hoàn","finding":"Huyết áp 150/84 mmHg, không phù, tĩnh mạch cổ không nổi, mạch ngoại vi đều."},{"group":"K","item":"Thể trạng","finding":"BMI 29 kg/m2, tỉnh, không tím."},{"group":"K","item":"Bụng, chân","finding":"Bụng mềm, hai chân không sưng đau, không dấu viêm tĩnh mạch."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo lúc đau và lặp lại sau 15–30 phút","duration_minutes":10,"result":"Nhịp xoang 84 l/p; ST chênh xuống 1,5 mm ở V4–V6, sóng T đảo sâu; không ST chênh lên; hết cơn đau, ST còn chênh xuống nhẹ."},{"name":"hs-troponin T lúc nhập viện và sau 1–3 giờ","duration_minutes":10,"result":"Lúc 0 giờ 48 ng/L, lúc 3 giờ 190 ng/L (tham chiếu dưới 14 ng/L): tăng rồi tăng tiếp, có động học."},{"name":"Glucose, HbA1c, creatinin, lipid, công thức máu","duration_minutes":10,"result":"Glucose 9,8 mmol/L; HbA1c 8,4%; creatinin 88 µmol/L, eGFR 62; LDL-C 3,6 mmol/L; Hb 124 g/L."},{"name":"Siêu âm tim","duration_minutes":15,"result":"EF 52%, giảm động vùng sau bên nhẹ, không hở van nặng, không tràn dịch."},{"name":"Nghiệm pháp gắng sức trên thảm chạy để chẩn đoán trước khi dùng thuốc","duration_minutes":10,"result":"Chống chỉ định khi đang có đau ngực nghỉ và troponin tăng, nguy cơ biến cố cao."}],"choices":{"diagnosis":{"ydx":["Viêm màng ngoài tim cấp","Thuyên tắc phổi","Nhồi máu cơ tim cấp không ST chênh lên (NSTEMI)","Đau thắt ngực ổn định"]},"actions":["Dùng thuốc tiêu sợi huyết đường tĩnh mạch","Nằm nghỉ, monitor điện tim, đường truyền, ghi điện tim lặp lại","Thêm chất ức chế P2Y12, statin liều cao và nitrat ngậm khi còn đau","Aspirin nhai và chống đông (enoxaparin 1 mg/kg tiêm dưới da mỗi 12 giờ, điều chỉnh theo eGFR)","Hội chẩn tim mạch can thiệp để chụp mạch vành trong 24 giờ","Cho về với hẹn khám ngoại trú vì ST không chênh lên","Làm nghiệm pháp gắng sức thảm chạy trước khi quyết định"]}}'::jsonb,
  'b50ab519fc9e23f81267fe5d6549235684c255c14d97cde099e721763462685e'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

