values (
  'noi-tim-mach-002',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-acs-esc-2023-0bce3c0fff0f","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/37622654/","title":"2023 ESC Guidelines for the management of acute coronary syndromes, Eur Heart J 2023.","organization":null,"year_version":null,"citation":"2023 ESC Guidelines for the management of acute coronary syndromes, Eur Heart J 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-002-2","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị hội chứng vành cấp không ST chênh lên, Hội Tim mạch học Việt Nam, bản cập nhật.","title":"Hướng dẫn chẩn đoán và điều trị hội chứng vành cấp không ST chênh lên, Hội Tim mạch học Việt Nam, bản cập nhật.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị hội chứng vành cấp không ST chênh lên, Hội Tim mạch học Việt Nam, bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-002-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh mạch vành.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh mạch vành.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh mạch vành.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đau thắt ngực ổn định","credit":"none"},{"text":"Nhồi máu cơ tim cấp không ST chênh lên (NSTEMI)","credit":"full"},{"text":"Thuyên tắc phổi","credit":"none"},{"text":"Viêm màng ngoài tim cấp","credit":"none"}]},"action_options":[{"text":"Nằm nghỉ, monitor điện tim, đường truyền, ghi điện tim lặp lại","time_minutes":2,"grade":"critical","rationale":"Cần phát hiện thay đổi ST, loạn nhịp khi đang có đau ngực nghỉ."},{"text":"Aspirin nhai và chống đông (enoxaparin 1 mg/kg tiêm dưới da mỗi 12 giờ, điều chỉnh theo eGFR)","time_minutes":2,"grade":"critical","rationale":"Điều trị thuốc chống huyết khối ngay khi chẩn đoán NSTE-ACS."},{"text":"Thêm chất ức chế P2Y12, statin liều cao và nitrat ngậm khi còn đau","time_minutes":2,"grade":"recommended","rationale":"Giảm biến cố; nitrat giảm đau do thiếu máu khi huyết áp cho phép."},{"text":"Hội chẩn tim mạch can thiệp để chụp mạch vành trong 24 giờ","time_minutes":2,"grade":"recommended","rationale":"Nguy cơ cao theo GRACE nên chiến lược xâm lấn sớm cải thiện tiên lượng."},{"text":"Làm nghiệm pháp gắng sức thảm chạy trước khi quyết định","time_minutes":1,"grade":"waste","rationale":"Không phù hợp khi có đau ngực nghỉ và men tim tăng."},{"text":"Cho về với hẹn khám ngoại trú vì ST không chênh lên","time_minutes":0,"grade":"harmful","rationale":"ST chênh xuống kèm troponin tăng là nhồi máu cơ tim, nguy cơ biến cố trong những ngày đầu."},{"text":"Dùng thuốc tiêu sợi huyết đường tĩnh mạch","time_minutes":0,"grade":"harmful","rationale":"Không có lợi và làm tăng xuất huyết trong NSTE-ACS."}],"teaching_explanation":"Ở hội chứng vành cấp không ST chênh lên, chẩn đoán dựa trên triệu chứng, điện tim và động học troponin; chia nguy cơ (GRACE) để chọn thời điểm chụp mạch. Tiêu sợi huyết không có chỉ định."}'::jsonb,
  '8fcdff3b51ee2617e0ec200549d3aa0dd4636135c5581f30b6007cc9271b76c5'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau đầu dữ dội, lú lẫn, huyết áp 232/128 mmHg","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":49,"sex":"nam","patient_label":"Ông T. Q. H. (mô phỏng)"},"presentation":{"intro":"Ông được vợ đưa vào cấp cứu vì đau đầu dữ dội, nôn và lú lẫn từ sáng.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":232,"dbp":128,"rr":20,"temperature_c":37,"spo2":97},"history":[{"question":"Đau đầu bắt đầu thế nào, có nôn, nhìn mờ không?","response":"Đau đầu âm ỉ hai ngày rồi tăng dữ dội từ sáng, nôn hai lần, nhìn mờ cả hai mắt."},{"question":"Có lú lẫn, co giật, yếu liệt, nói khó không?","response":"Vợ thấy ông nói chuyện lẫn, hỏi trước quên sau; không co giật, không yếu liệt, không méo miệng."},{"question":"Có đau ngực, khó thở, đau lưng không?","response":"Tức ngực nhẹ, không khó thở, không đau lưng xé."},{"question":"Tiền sử tăng huyết áp và thuốc đang dùng?","response":"Tăng huyết áp 6 năm, tự ngưng thuốc 3 tuần nay vì thấy khỏe; trước đó dùng amlodipin và losartan."},{"question":"Gần đây có dùng thuốc, chất kích thích, thuốc cảm giảm nghẹt mũi, thuốc giảm đau, rượu nặng không?","response":"Không dùng chất kích thích; không dùng thuốc cảm; uống rượu vừa."},{"question":"Có chấn thương đầu, bệnh thận, đang mang thai (đối với nữ), bệnh tuyến thượng thận không?","response":"Không chấn thương đầu; chưa biết bệnh thận; không có cơn đau đầu đỏ bừng mặt đánh trống ngực đột ngột trước đây."},{"question":"Ăn uống, hút thuốc?","response":"Ăn mặn, hút nửa gói mỗi ngày."}],"examination":[{"group":"K","item":"Thần kinh","finding":"Lơ mơ, định hướng kém, GCS 14 (M6 V4 E4), không dấu thần kinh khu trú, không cứng gáy; đồng tử đều phản xạ tốt."},{"group":"K","item":"Đáy mắt","finding":"Phù gai thị hai bên, xuất huyết hình ngọn lửa và xuất tiết võng mạc."},{"group":"K","item":"Tim phổi","finding":"Tim đều 98 l/p, T2 vang ở ổ chủ, không tiếng thổi; phổi vài ran ẩm nhỏ ở đáy hai bên."},{"group":"K","item":"Huyết áp hai tay và mạch","finding":"Huyết áp tay phải 232/128, tay trái 228/126 mmHg; mạch hai bên đều, không tiếng thổi động mạch cảnh."},{"group":"K","item":"Bụng, phù","finding":"Bụng mềm, không âm thổi vùng thượng vị; không phù."}],"investigations":[{"name":"CT sọ não không cản quang","duration_minutes":40,"result":"Không xuất huyết, không nhồi máu mới, không khối choán chỗ; có dấu hiệu phù não nhẹ lan tỏa vùng sau."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang 98 l/p, dày thất trái, không thay đổi ST cấp."},{"name":"Creatinin, ure, điện giải, tổng phân tích nước tiểu","duration_minutes":10,"result":"Creatinin 142 µmol/L, ure 11 mmol/L, K 4,0 mmol/L; nước tiểu protein 2+, hồng cầu 1+."},{"name":"Troponin siêu nhạy, X-quang ngực, công thức máu","duration_minutes":10,"result":"Troponin 22 ng/L (tham chiếu dưới 34), tim to nhẹ, xung huyết phổi nhẹ; Hb 138 g/L, tiểu cầu bình thường."},{"name":"Cộng hưởng từ sọ não, mạch máu khẩn trước mọi thuốc hạ áp","duration_minutes":10,"result":"Làm trước khi hạ áp là không cần thiết và gây chậm trễ khi CT đã loại trừ xuất huyết."}],"choices":{"diagnosis":{"ydx":["Cơn tăng huyết áp không triệu chứng đơn thuần","Cấp cứu tăng huyết áp với bệnh não tăng huyết áp","Xuất huyết não tự phát","Viêm màng não do vi khuẩn"]},"actions":["Chụp CT sọ loại trừ xuất huyết và đánh giá chức năng thận, nước tiểu","Nhập hồi sức tim mạch, theo dõi tri giác, lượng nước tiểu","Cho thuốc lợi tiểu quai tiêm tĩnh mạch liều cao thường quy","Truyền nicardipin hoặc labetalol tĩnh mạch chỉnh liều đạt mục tiêu giảm huyết áp trung bình 20–25% trong giờ đầu","Cho về uống thuốc huyết áp lại như thường","Ngậm nifedipin tác dụng nhanh để hạ nhanh","Nằm đầu cao, monitor, hai đường truyền, theo dõi huyết áp liên tục"]}}'::jsonb,
  '154b56e11c166ad2135d74d925b4726867abd3e5ff45bba6f3c21cc26d0ce66d'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-tim-mach-003',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-003-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010 và cập nhật Hội Tim mạch học Việt Nam 2022.","title":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010 và cập nhật Hội Tim mạch học Việt Nam 2022.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010 và cập nhật Hội Tim mạch học Việt Nam 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-htn-esc-2018","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/30165516/","title":"2018 ESC/ESH Guidelines for the management of arterial hypertension, Eur Heart J 2018.","organization":null,"year_version":null,"citation":"2018 ESC/ESH Guidelines for the management of arterial hypertension, Eur Heart J 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-003-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Tăng huyết áp.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Tăng huyết áp.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Tăng huyết áp.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Cơn tăng huyết áp không triệu chứng đơn thuần","credit":"none"},{"text":"Xuất huyết não tự phát","credit":"none"},{"text":"Cấp cứu tăng huyết áp với bệnh não tăng huyết áp","credit":"full"},{"text":"Viêm màng não do vi khuẩn","credit":"none"}]},"action_options":[{"text":"Nằm đầu cao, monitor, hai đường truyền, theo dõi huyết áp liên tục","time_minutes":2,"grade":"critical","rationale":"Cần theo dõi sát khi dùng thuốc hạ áp tĩnh mạch."},{"text":"Truyền nicardipin hoặc labetalol tĩnh mạch chỉnh liều đạt mục tiêu giảm huyết áp trung bình 20–25% trong giờ đầu","time_minutes":2,"grade":"critical","rationale":"Giảm tổn thương cơ quan đích nhưng tránh thiếu máu não do hạ áp quá nhanh."},{"text":"Chụp CT sọ loại trừ xuất huyết và đánh giá chức năng thận, nước tiểu","time_minutes":2,"grade":"critical","rationale":"Phân biệt với xuất huyết não và tìm tổn thương cơ quan đích."},{"text":"Nhập hồi sức tim mạch, theo dõi tri giác, lượng nước tiểu","time_minutes":2,"grade":"critical","rationale":"Bệnh não tăng huyết áp cần theo dõi liên tục."},{"text":"Cho thuốc lợi tiểu quai tiêm tĩnh mạch liều cao thường quy","time_minutes":1,"grade":"waste","rationale":"Chỉ dùng khi có quá tải thể tích hoặc phù phổi; ở đây chỉ có ran nhẹ."},{"text":"Ngậm nifedipin tác dụng nhanh để hạ nhanh","time_minutes":0,"grade":"harmful","rationale":"Hạ áp mạnh và không kiểm soát làm giảm tưới máu não, tim, thận."},{"text":"Cho về uống thuốc huyết áp lại như thường","time_minutes":0,"grade":"harmful","rationale":"Ca có bệnh não và phù gai thị cần can thiệp khẩn tại hồi sức."}],"teaching_explanation":"Phân biệt cấp cứu tăng huyết áp (có tổn thương cơ quan đích) với cơn tăng huyết áp không triệu chứng; cấp cứu cần thuốc tĩnh mạch hạ áp có kiểm soát, tránh hạ nhanh quá mức và tìm nguyên nhân sau đó."}'::jsonb,
  '3e97fdf21b6bb9d39e21efe66abea83b46b4532e0fd84b2f226bf32e9739a4f3'
)
