insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở dữ dội về đêm, khạc bọt hồng ở người nhồi máu cơ tim cũ","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nam","patient_label":"Ông P. V. D. (mô phỏng)"},"presentation":{"intro":"Ông được đưa vào cấp cứu lúc 2 giờ sáng vì khó thở dữ dội phải ngồi dậy, khạc đờm bọt hồng.","place":null,"clock":null,"night":false},"vitals":{"hr":114,"sbp":158,"dbp":96,"rr":34,"temperature_c":37.1,"spo2":84},"history":[{"question":"Khó thở bắt đầu thế nào, có phải ngồi dậy mới thở được không?","response":"Đang ngủ thì tỉnh dậy vì ngộp, phải ngồi thẳng, khó thở tăng nhanh trong 1 giờ; những ngày qua phải kê ba gối."},{"question":"Có khạc bọt hồng, ho, đau ngực, hồi hộp không?","response":"Ho khạc bọt hồng loãng, hồi hộp, không đau ngực dữ dội."},{"question":"Tiền sử bệnh tim, nhồi máu cơ tim, tăng huyết áp, đái tháo đường?","response":"Nhồi máu cơ tim cách đây 5 năm, EF 35%; tăng huyết áp; đái tháo đường típ 2."},{"question":"Thuốc đang dùng và tuân thủ ra sao?","response":"Có furosemid, enalapril, bisoprolol nhưng hai tuần nay ngưng thuốc lợi tiểu vì sợ tiểu nhiều."},{"question":"Gần đây có ăn mặn, tiệc, uống nhiều nước, nhiễm trùng, dùng thuốc giảm đau chống viêm không?","response":"Ăn tiệc cưới nhiều muối ba ngày trước; có uống thuốc giảm đau vì đau lưng; không sốt."},{"question":"Có phù chân, tăng cân, tiểu ít không?","response":"Phù hai chân, tăng 3 kg trong 10 ngày, tiểu ít."},{"question":"Có sốt, ho đờm mủ, đau ngực kiểu màng phổi không?","response":"Không sốt, không đờm mủ."}],"examination":[{"group":"K","item":"Hô hấp","finding":"Thở nhanh 34 l/p, co kéo cơ hô hấp phụ, ran ẩm dâng đầy từ đáy lên quá nửa hai phổi, vài ran rít."},{"group":"K","item":"Tim","finding":"Nhịp nhanh 114 l/p, T3 ngựa phi, tiếng thổi tâm thu mỏm 2/6; tĩnh mạch cổ nổi."},{"group":"K","item":"Phù và gan","finding":"Phù mềm hai chân đến gối, gan to 2 cm dưới bờ sườn, phản hồi gan–tĩnh mạch cổ dương tính."},{"group":"K","item":"Tưới máu","finding":"Da ẩm, chi ấm, thời gian làm đầy mao mạch 2 giây, huyết áp 158/96 mmHg (type ấm–ướt)."},{"group":"K","item":"Thần kinh","finding":"Tỉnh, kích thích, nói ngắt quãng."}],"investigations":[{"name":"SpO2 liên tục và khí máu động mạch","duration_minutes":10,"result":"SpO2 84% khí trời; pH 7,36, PaO2 54, PaCO2 38, lactate 1,8 mmol/L."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang nhanh 114 l/p, sóng Q cũ V1–V4, block nhánh trái không hoàn toàn; không ST chênh lên mới."},{"name":"NT-proBNP, troponin siêu nhạy","duration_minutes":10,"result":"NT-proBNP 8200 pg/mL (tham chiếu dưới 300); hs-troponin 52 ng/L hơi tăng, ổn định trong ba giờ."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Bóng tim to, phổi mờ dạng cánh bướm hai bên, đường Kerley B, tràn dịch màng phổi nhỏ hai bên."},{"name":"Siêu âm tim tại giường","duration_minutes":15,"result":"EF 28%, thất trái giãn, vận động kém vùng trước vách, hở hai lá mức vừa, IVC giãn."},{"name":"Creatinin, điện giải","duration_minutes":10,"result":"Creatinin 128 µmol/L, K 4,4, Na 133 mmol/L."},{"name":"CT ngực cản quang khẩn để xác định mọi ca khó thở cấp","duration_minutes":40,"result":"Không cần thiết, làm chậm xử trí khi lâm sàng và X-quang đã chẩn đoán phù phổi."}],"choices":{"diagnosis":{"ydx":["Thuyên tắc phổi cấp","Đợt cấp COPD","Hen tim hoàn toàn do bệnh phổi","Suy tim cấp mất bù, phù phổi cấp huyết động (type ướt–ấm), bệnh tim thiếu máu cục bộ"]},"actions":["Ngồi đầu cao, gắn monitor, thở oxy hoặc CPAP/NIV để đạt SpO2 trên 94%","Furosemid 40–80 mg tiêm tĩnh mạch và nitroglycerin tĩnh mạch chỉnh liều theo huyết áp","Tìm yếu tố thúc đẩy: điện tim, troponin, siêu âm tim, hỏi về ngưng thuốc và NSAID","Cho thuốc giảm đau NSAID cho đau lưng","Thông tiểu hoặc theo dõi nước tiểu, theo dõi điện giải, creatinin sau lợi tiểu","Dùng morphin tiêm tĩnh mạch để giảm khó thở","Truyền nhanh dịch muối đẳng trương để nâng huyết áp"]}}'::jsonb,
  '7b3321c592641c9a2a96462eccd1fec634d7eab3e73cde0fff86996cf50dd43e'
)
