values (
  'noi-tim-mach-004',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-004-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị suy tim, Bộ Y tế Việt Nam, 2020.","title":"Hướng dẫn chẩn đoán và điều trị suy tim, Bộ Y tế Việt Nam, 2020.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị suy tim, Bộ Y tế Việt Nam, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-hf-esc-2021-3c4bd6c322d6","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/34447992/","title":"2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure, Eur Heart J 2021.","organization":null,"year_version":null,"citation":"2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure, Eur Heart J 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-004-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Suy tim.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Suy tim.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Suy tim.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"essential"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đợt cấp COPD","credit":"none"},{"text":"Hen tim hoàn toàn do bệnh phổi","credit":"none"},{"text":"Thuyên tắc phổi cấp","credit":"none"},{"text":"Suy tim cấp mất bù, phù phổi cấp huyết động (type ướt–ấm), bệnh tim thiếu máu cục bộ","credit":"full"}]},"action_options":[{"text":"Ngồi đầu cao, gắn monitor, thở oxy hoặc CPAP/NIV để đạt SpO2 trên 94%","time_minutes":2,"grade":"critical","rationale":"Giảm công thở, giảm tiền tải và cải thiện oxy máu."},{"text":"Furosemid 40–80 mg tiêm tĩnh mạch và nitroglycerin tĩnh mạch chỉnh liều theo huyết áp","time_minutes":2,"grade":"critical","rationale":"Giảm tiền tải, giảm xung huyết phổi nhanh khi huyết áp còn cao."},{"text":"Thông tiểu hoặc theo dõi nước tiểu, theo dõi điện giải, creatinin sau lợi tiểu","time_minutes":2,"grade":"critical","rationale":"Đánh giá đáp ứng lợi tiểu (đủ trên 100–150 ml/giờ ở 6 giờ đầu)."},{"text":"Tìm yếu tố thúc đẩy: điện tim, troponin, siêu âm tim, hỏi về ngưng thuốc và NSAID","time_minutes":2,"grade":"critical","rationale":"Điều chỉnh nguyên nhân làm mất bù."},{"text":"Dùng morphin tiêm tĩnh mạch để giảm khó thở","time_minutes":1,"grade":"waste","rationale":"Không thường quy, có thể gây ức chế hô hấp, tăng nhu cầu thở máy."},{"text":"Truyền nhanh dịch muối đẳng trương để nâng huyết áp","time_minutes":0,"grade":"harmful","rationale":"Huyết áp cao, phổi đã ngập nước, truyền dịch làm nặng thêm."},{"text":"Cho thuốc giảm đau NSAID cho đau lưng","time_minutes":0,"grade":"harmful","rationale":"NSAID giữ nước, muối và làm nặng suy tim."}],"teaching_explanation":"Phù phổi cấp ở người suy tim thường do mất bù với tăng tiền tải: ưu tiên oxy hoặc thông khí hỗ trợ, lợi tiểu quai và nitrat tĩnh mạch nếu huyết áp cho phép. Cần tìm yếu tố thúc đẩy như ngưng lợi tiểu, NSAID, thiếu máu cơ tim."}'::jsonb,
