insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Hồi hộp, tim đập không đều 2 ngày, mạch 148 lần/phút","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":66,"sex":"nữ","patient_label":"Bà H. T. L. (mô phỏng)"},"presentation":{"intro":"Bà đến cấp cứu vì hồi hộp, đánh trống ngực và mệt hai ngày, huyết động còn ổn định.","place":null,"clock":null,"night":false},"vitals":{"hr":148,"sbp":118,"dbp":72,"rr":20,"temperature_c":36.9,"spo2":97},"history":[{"question":"Hồi hộp bắt đầu khi nào, liên tục hay từng cơn, tim đập đều hay không?","response":"Bắt đầu cách đây khoảng 2 ngày, lúc 8 giờ sáng, đập loạn xạ liên tục, không đều."},{"question":"Có đau ngực, khó thở, choáng, ngất không?","response":"Hơi khó thở khi đi lại, choáng nhẹ; không đau ngực, không ngất."},{"question":"Tiền sử tăng huyết áp, đái tháo đường, bệnh tim, đột quỵ?","response":"Tăng huyết áp 10 năm dùng amlodipin; không đái tháo đường; không bệnh van tim, không đột quỵ."},{"question":"Có dấu hiệu cường giáp, sụt cân, run tay, nóng sợ nóng không?","response":"Không sụt cân, không run tay, không sợ nóng."},{"question":"Uống rượu, cà phê, thuốc kích thích, thuốc cảm, thuốc lá không?","response":"Không uống rượu; 2 ly cà phê mỗi sáng; không hút thuốc."},{"question":"Có sốt, ho, nhiễm trùng gần đây không?","response":"Không sốt, không ho."},{"question":"Có đang dùng thuốc chống đông hoặc có tiền sử xuất huyết không?","response":"Không dùng thuốc chống đông; chưa từng xuất huyết lớn."},{"question":"Sinh hoạt hằng ngày?","response":"Còn tự đi lại và làm việc nhà."}],"examination":[{"group":"K","item":"Mạch và nhịp tim","finding":"Nhịp tim hoàn toàn không đều, tần số thất 148 l/p, mạch quay thấp hơn nhịp tim (hụt mạch)."},{"group":"K","item":"Huyết động","finding":"Huyết áp 118/72 mmHg, chi ấm, tỉnh, không dấu hiệu sốc."},{"group":"K","item":"Phổi và tĩnh mạch cổ","finding":"Phổi không ran, tĩnh mạch cổ không nổi, không phù."},{"group":"K","item":"Tim: tiếng thổi","finding":"Không tiếng thổi van đáng kể; T1 thay đổi cường độ."},{"group":"K","item":"Tuyến giáp","finding":"Không to, không rung miu, mắt không lồi."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo","duration_minutes":10,"result":"Nhịp không đều hoàn toàn, không có sóng P, sóng f nhỏ, QRS hẹp 148 l/p; không ST chênh lên."},{"name":"TSH, FT4, điện giải, creatinin, công thức máu, đường huyết","duration_minutes":10,"result":"TSH 1,8 mU/L bình thường, K 4,0, Mg 0,85 mmol/L, creatinin 78 µmol/L, Hb 128 g/L."},{"name":"Siêu âm tim qua thành ngực","duration_minutes":15,"result":"EF 56%, nhĩ trái 44 mm, không bệnh van trung bình–nặng, không huyết khối thấy được trên siêu âm qua thành ngực."},{"name":"Troponin siêu nhạy","duration_minutes":10,"result":"12 ng/L, không tăng."},{"name":"X-quang ngực","duration_minutes":10,"result":"Bóng tim bình thường, phổi không xung huyết."},{"name":"Sốc điện chuyển nhịp ngay không chuẩn bị chống đông dù huyết động ổn định","duration_minutes":10,"result":"Không có chỉ định; rung nhĩ trên 48 giờ cần chống đông trước hoặc TEE loại trừ huyết khối."}],"choices":{"diagnosis":{"ydx":["Cơn nhịp nhanh trên thất do vòng vào lại","Cuồng nhĩ 2:1","Rung nhĩ không do bệnh van tim, đáp ứng thất nhanh, huyết động ổn định","Nhịp nhanh thất"]},"actions":["Sốc điện chuyển nhịp ngay khi chưa chống đông","Dùng digoxin làm thuốc đầu tay duy nhất","Dùng verapamil tĩnh mạch kết hợp chẹn beta tĩnh mạch đồng thời","Xét nghiệm TSH, điện giải, siêu âm tim, tính CHA2DS2-VASc","Bắt đầu chống đông (ví dụ rivaroxaban hoặc apixaban hoặc heparin trọng lượng phân tử thấp rồi chuyển)","Kiểm soát tần số bằng diltiazem hoặc metoprolol tĩnh mạch/uống, chỉnh theo huyết áp","Monitor điện tim, đường truyền, đánh giá huyết động và điện tim 12 chuyển đạo"]}}'::jsonb,
  '6c0fddada708de2a1771c071f06682bfcb5e9ce8c0a5a614d00c9e748908dee3'
)
