values (
  'noi-tim-mach-005',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-af-esc-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/32860505/","title":"2020 ESC Guidelines for the diagnosis and management of atrial fibrillation, Eur Heart J 2021.","organization":null,"year_version":null,"citation":"2020 ESC Guidelines for the diagnosis and management of atrial fibrillation, Eur Heart J 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-005-2","resource_type":"other","source":"Khuyến cáo về chẩn đoán và điều trị rung nhĩ, Hội Tim mạch học Việt Nam, bản cập nhật.","title":"Khuyến cáo về chẩn đoán và điều trị rung nhĩ, Hội Tim mạch học Việt Nam, bản cập nhật.","organization":null,"year_version":null,"citation":"Khuyến cáo về chẩn đoán và điều trị rung nhĩ, Hội Tim mạch học Việt Nam, bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-005-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Rối loạn nhịp tim.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Rối loạn nhịp tim.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Rối loạn nhịp tim.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Rung nhĩ không do bệnh van tim, đáp ứng thất nhanh, huyết động ổn định","credit":"full"},{"text":"Cơn nhịp nhanh trên thất do vòng vào lại","credit":"none"},{"text":"Cuồng nhĩ 2:1","credit":"none"},{"text":"Nhịp nhanh thất","credit":"none"}]},"action_options":[{"text":"Monitor điện tim, đường truyền, đánh giá huyết động và điện tim 12 chuyển đạo","time_minutes":2,"grade":"critical","rationale":"Xác nhận rung nhĩ, loại trừ rối loạn nhịp khác và đánh giá có bất ổn huyết động hay không."},{"text":"Kiểm soát tần số bằng diltiazem hoặc metoprolol tĩnh mạch/uống, chỉnh theo huyết áp","time_minutes":2,"grade":"critical","rationale":"EF bảo tồn, huyết động ổn định nên giảm tần số thất là ưu tiên."},{"text":"Xét nghiệm TSH, điện giải, siêu âm tim, tính CHA2DS2-VASc","time_minutes":2,"grade":"recommended","rationale":"Tìm nguyên nhân và quyết định chống đông dài hạn."},{"text":"Bắt đầu chống đông (ví dụ rivaroxaban hoặc apixaban hoặc heparin trọng lượng phân tử thấp rồi chuyển)","time_minutes":2,"grade":"recommended","rationale":"CHA2DS2-VASc 3 điểm (tuổi 65–74, nữ, tăng huyết áp) chỉ định chống đông."},{"text":"Dùng digoxin làm thuốc đầu tay duy nhất","time_minutes":1,"grade":"waste","rationale":"Tác dụng chậm, kiểm soát tần số khi gắng sức kém; để dành cho suy tim hoặc hạ huyết áp."},{"text":"Sốc điện chuyển nhịp ngay khi chưa chống đông","time_minutes":0,"grade":"harmful","rationale":"Rung nhĩ kéo dài trên 48 giờ có thể có huyết khối nhĩ trái, nguy cơ đột quỵ."},{"text":"Dùng verapamil tĩnh mạch kết hợp chẹn beta tĩnh mạch đồng thời","time_minutes":0,"grade":"harmful","rationale":"Phối hợp có nguy cơ ngừng xoang, block nhĩ thất."}],"teaching_explanation":"Rung nhĩ có đáp ứng thất nhanh và huyết động ổn định: ưu tiên kiểm soát tần số, đánh giá nguy cơ đột quỵ bằng CHA2DS2-VASc và chống đông; không chuyển nhịp vội khi khởi phát hơn 48 giờ nếu chưa an toàn."}'::jsonb,
  '8ee5e0d82f8d9b708bade95bf8a7f8262b6185ec1077c7adfca8f1234297f11a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tăng huyết áp mạn cần lập kế hoạch điều trị ngoại trú","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":54,"sex":"nam","patient_label":"Ông Đ. M. K. (mô phỏng)"},"presentation":{"intro":"Ông đến phòng khám vì đo huyết áp tại cơ quan nhiều lần cao, không triệu chứng.","place":null,"clock":null,"night":false},"vitals":{"hr":78,"sbp":158,"dbp":98,"rr":16,"temperature_c":36.7,"spo2":98},"history":[{"question":"Huyết áp được phát hiện khi nào, đo thế nào, mức bao nhiêu?","response":"Hai tháng nay đo tại cơ quan 150–165/92–100 mmHg; chưa uống thuốc."},{"question":"Có đau đầu, chóng mặt, hồi hộp, đau ngực, khó thở không?","response":"Thỉnh thoảng nặng đầu buổi sáng; không đau ngực, không khó thở, không hồi hộp."},{"question":"Có triệu chứng gợi ý nguyên nhân thứ phát như ngáy ngưng thở, đánh trống ngực từng cơn, yếu cơ, tiểu đêm nhiều?","response":"Ngáy to, đôi khi ngủ gật ban ngày; không có cơn đỏ bừng mặt, không yếu cơ."},{"question":"Tiền sử đái tháo đường, rối loạn lipid, bệnh thận, đột quỵ, bệnh tim?","response":"Rối loạn lipid phát hiện năm ngoái chưa điều trị; không đái tháo đường, không bệnh thận."},{"question":"Gia đình có ai tăng huyết áp, đột quỵ, bệnh mạch vành không?","response":"Cha bị tăng huyết áp và đột quỵ ở 65 tuổi."},{"question":"Lối sống: muối, rượu, thuốc lá, vận động?","response":"Ăn mặn, uống bia 3–4 lon cuối tuần, hút nửa gói mỗi ngày, ít vận động."},{"question":"Đang dùng thuốc nào làm tăng huyết áp (NSAID, thuốc cảm, corticoid, thuốc ngừa thai)?","response":"Thỉnh thoảng uống thuốc giảm đau chống viêm vì đau lưng."},{"question":"Nghề nghiệp?","response":"Nhân viên văn phòng, hay thức khuya."}],"examination":[{"group":"K","item":"Đo huyết áp đúng quy trình","finding":"Hai tay, ngồi nghỉ 5 phút: tay phải 158/98 và 156/96 mmHg; chênh hai tay dưới 10 mmHg."},{"group":"K","item":"Nhân trắc","finding":"BMI 29,5 kg/m2; vòng bụng 98 cm."},{"group":"K","item":"Tim phổi","finding":"Tim đều, T2 mạnh ở ổ chủ, không tiếng thổi; phổi trong."},{"group":"K","item":"Đáy mắt, thần kinh","finding":"Đáy mắt có hẹp tiểu động mạch độ I; thần kinh bình thường."},{"group":"K","item":"Bụng, mạch đùi","finding":"Không âm thổi vùng bụng, mạch đùi bắt rõ, không phù."}],"investigations":[{"name":"Đo huyết áp lưu động 24 giờ hoặc đo tại nhà để xác nhận","duration_minutes":10,"result":"Trung bình 24 giờ 148/92 mmHg, ban ngày 152/95, ban đêm 138/84: xác nhận tăng huyết áp."},{"name":"Creatinin, eGFR, điện giải, glucose, HbA1c, lipid máu, acid uric","duration_minutes":10,"result":"Creatinin 86 µmol/L, eGFR 96, K 4,2 mmol/L, glucose 5,6 mmol/L, HbA1c 5,7%, LDL-C 3,8 mmol/L, TG 2,3 mmol/L."},{"name":"Tổng phân tích nước tiểu và tỉ lệ albumin/creatinin niệu","duration_minutes":10,"result":"Không có protein; ACR 18 mg/g (bình thường dưới 30)."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang 78 l/p, dày thất trái nhẹ theo chỉ số Sokolow-Lyon 36 mm."},{"name":"Siêu âm tim","duration_minutes":15,"result":"EF 62%, dày vách liên thất 12 mm, rối loạn tâm trương độ I."},{"name":"MRI mạch thận và CT bụng chụp mạch ngay cho mọi người bệnh tăng huyết áp mới","duration_minutes":40,"result":"Không có chỉ định thường quy khi không có dấu hiệu gợi ý nguyên nhân thứ phát."}],"choices":{"diagnosis":{"ydx":["Tăng huyết áp nguyên phát độ 2 có nguy cơ tim mạch cao (có tổn thương cơ quan đích)","Cơn tăng huyết áp cấp cứu","Tăng huyết áp thứ phát do hẹp động mạch thận","Tăng huyết áp áo choàng trắng đơn thuần"]},"actions":["Chỉ định statin theo nguy cơ và khám chuyên khoa giấc ngủ","Dùng NSAID kéo dài cho đau lưng","Xác nhận chẩn đoán bằng đo tại nhà hoặc lưu động và đánh giá nguy cơ tim mạch toàn bộ","Làm MRI mạch thận ngay","Xét nghiệm creatinin, kali, lipid, đường huyết, nước tiểu, điện tim, siêu âm tim","Bắt đầu phối hợp thuốc liều cố định (ức chế men chuyển hoặc chẹn thụ thể + chẹn kênh calci) và tư vấn lối sống","Ngậm nifedipin ngắn để hạ nhanh về bình thường"]}}'::jsonb,
  '4fd3e6c62b6a2535893f2676438048c41e26d09192e2e93b41c2e7bec94b5146'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-tim-mach-006',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-006-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010.","title":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị tăng huyết áp, Bộ Y tế Việt Nam, 2010.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-006-2","resource_type":"other","source":"Khuyến cáo của Hội Tim mạch học Việt Nam về chẩn đoán và điều trị tăng huyết áp, 2022.","title":"Khuyến cáo của Hội Tim mạch học Việt Nam về chẩn đoán và điều trị tăng huyết áp, 2022.","organization":null,"year_version":null,"citation":"Khuyến cáo của Hội Tim mạch học Việt Nam về chẩn đoán và điều trị tăng huyết áp, 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-htn-esc-2018","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/30165516/","title":"2018 ESC/ESH Guidelines for the management of arterial hypertension, Eur Heart J 2018.","organization":null,"year_version":null,"citation":"2018 ESC/ESH Guidelines for the management of arterial hypertension, Eur Heart J 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tăng huyết áp áo choàng trắng đơn thuần","credit":"none"},{"text":"Tăng huyết áp nguyên phát độ 2 có nguy cơ tim mạch cao (có tổn thương cơ quan đích)","credit":"full"},{"text":"Tăng huyết áp thứ phát do hẹp động mạch thận","credit":"none"},{"text":"Cơn tăng huyết áp cấp cứu","credit":"none"}]},"action_options":[{"text":"Xác nhận chẩn đoán bằng đo tại nhà hoặc lưu động và đánh giá nguy cơ tim mạch toàn bộ","time_minutes":2,"grade":"critical","rationale":"Phân biệt tăng huyết áp thật với áo choàng trắng và định mức nguy cơ."},{"text":"Bắt đầu phối hợp thuốc liều cố định (ức chế men chuyển hoặc chẹn thụ thể + chẹn kênh calci) và tư vấn lối sống","time_minutes":2,"grade":"critical","rationale":"Phối hợp sớm tăng khả năng đạt mục tiêu và tuân thủ."},{"text":"Xét nghiệm creatinin, kali, lipid, đường huyết, nước tiểu, điện tim, siêu âm tim","time_minutes":2,"grade":"recommended","rationale":"Tìm tổn thương cơ quan đích và bệnh đi kèm."},{"text":"Chỉ định statin theo nguy cơ và khám chuyên khoa giấc ngủ","time_minutes":2,"grade":"recommended","rationale":"LDL-C 3,8 mmol/L và ngáy to nghi ngưng thở khi ngủ, yếu tố làm tăng huyết áp."},{"text":"Làm MRI mạch thận ngay","time_minutes":1,"grade":"waste","rationale":"Chưa có dấu hiệu gợi ý nguyên nhân thứ phát; đắt và không cần."},{"text":"Dùng NSAID kéo dài cho đau lưng","time_minutes":0,"grade":"harmful","rationale":"NSAID làm tăng huyết áp, giữ muối nước, hại thận."},{"text":"Ngậm nifedipin ngắn để hạ nhanh về bình thường","time_minutes":0,"grade":"harmful","rationale":"Hạ áp quá nhanh không cần thiết, gây thiếu máu cơ quan."}],"teaching_explanation":"Tăng huyết áp mạn cần xác nhận bằng đo ngoài phòng khám, đánh giá nguy cơ và tổn thương cơ quan đích, bắt đầu phối hợp thuốc đúng nhóm cùng thay đổi lối sống, và hẹn tái khám chỉnh liều."}'::jsonb,
  '18ac1b548ed789fe7f61fb664fa10be8c2c9774defdb6793f04507707f4c1684'
)
