insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở nặng, khò khè, nói từng từ ở người bị hen","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":28,"sex":"nữ","patient_label":"Chị V. T. N. (mô phỏng)"},"presentation":{"intro":"Chị được đưa vào cấp cứu vì khó thở tăng dần từ chiều, xịt thuốc giãn phế quản nhiều lần không đỡ.","place":null,"clock":null,"night":false},"vitals":{"hr":128,"sbp":124,"dbp":76,"rr":32,"temperature_c":37,"spo2":89},"history":[{"question":"Khó thở bắt đầu thế nào, có khò khè, ho, tức ngực không?","response":"Ho và khò khè từ tối qua, chiều nay khó thở tăng nhanh, tức ngực, không nói trọn câu."},{"question":"Đã dùng thuốc xịt gì, bao nhiêu lần, có đỡ không?","response":"Xịt salbutamol khoảng 10 nhát trong 3 giờ, chỉ đỡ vài phút."},{"question":"Tiền sử hen, nhập viện, đặt nội khí quản trước đây?","response":"Hen từ nhỏ, dùng thuốc dự phòng không đều; năm ngoái nhập viện một lần, chưa đặt nội khí quản."},{"question":"Yếu tố khởi phát: nhiễm trùng hô hấp, tiếp xúc dị nguyên, thuốc (aspirin, chẹn beta), khói?","response":"Cảm sổ mũi 3 ngày; dọn nhà nhiều bụi; không dùng aspirin hay chẹn beta."},{"question":"Có sốt, đờm mủ, đau ngực kiểu màng phổi không?","response":"Không sốt; đờm trắng ít."},{"question":"Có khó nuốt, phù môi mặt, nổi mề đay (loại phản vệ) không?","response":"Không phù mặt, không mề đay."},{"question":"Có tiền sử dị ứng, viêm mũi dị ứng, chàm không?","response":"Viêm mũi dị ứng, dị ứng bụi nhà."},{"question":"Có hút thuốc lá không?","response":"Không hút thuốc."}],"examination":[{"group":"K","item":"Hô hấp: tần số và co kéo","finding":"Thở 32 l/p, co kéo cơ ức đòn chũm và liên sườn, nói từng từ."},{"group":"K","item":"Phổi nghe","finding":"Ran rít, ran ngáy lan tỏa hai phổi cả hai thì, rì rào phế nang giảm ở đáy; chưa có phổi câm."},{"group":"K","item":"Tim mạch","finding":"Tim nhanh 128 l/p, huyết áp 124/76 mmHg, mạch nghịch đảo khoảng 18 mmHg."},{"group":"K","item":"Tri giác","finding":"Tỉnh, vật vã nhưng còn hợp tác; không tím tái."},{"group":"K","item":"Da, họng","finding":"Không nổi mề đay, không phù thanh quản."}],"investigations":[{"name":"Đo lưu lượng đỉnh (PEF) hoặc FEV1 nếu thực hiện được","duration_minutes":10,"result":"PEF 140 L/phút, khoảng 28% so với giá trị dự đoán (500 L/phút)."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,38; PaO2 60 mmHg; PaCO2 44 mmHg; HCO3 25: PaCO2 đã trở về bình thường trong khi đang thở nhanh, cảnh báo kiệt sức."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Phổi tăng sáng, không tràn khí màng phổi, không đông đặc."},{"name":"Công thức máu, điện giải","duration_minutes":10,"result":"Bạch cầu 13,5 G/L, bạch cầu ưa acid 0,3 G/L; K 3,6 mmol/L."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang nhanh 128 l/p, không thiếu máu cơ tim."},{"name":"CT ngực độ phân giải cao ngay để chẩn đoán trước khi điều trị","duration_minutes":40,"result":"Không cần khi lâm sàng điển hình; trì hoãn điều trị cơn nặng."}],"choices":{"diagnosis":{"ydx":["Cơn hen phế quản cấp nặng, nguy cơ suy hô hấp","Đợt cấp COPD","Tràn khí màng phổi tự phát","Phản vệ có co thắt phế quản"]},"actions":["Salbutamol 2,5–5 mg phun khí dung kèm ipratropium mỗi 20 phút trong giờ đầu","Ngồi, monitor SpO2, thở oxy duy trì SpO2 93–95%","Corticoid toàn thân sớm (methylprednisolon tĩnh mạch hoặc prednisolon uống 40–50 mg)","Magnesium sulfat tĩnh mạch nếu đáp ứng kém sau giờ đầu","Dùng thuốc an thần để giúp chị nghỉ ngơi","Kháng sinh thường quy","Theo dõi khí máu lặp lại và chuẩn bị chuyển hồi sức"]}}'::jsonb,
  '1bd97a513f894c3d4cf31355d68718d9d9fcde2529167d6f4bfa21012cd86610'
)
