insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-ho-hap-001',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-001-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị hen phế quản, Bộ Y tế Việt Nam, 2016.","title":"Hướng dẫn chẩn đoán và điều trị hen phế quản, Bộ Y tế Việt Nam, 2016.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị hen phế quản, Bộ Y tế Việt Nam, 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-gina-2025-7da41e42542c","resource_type":"guideline","source":"https://ginasthma.org/wp-content/uploads/2025/11/GINA-Summary-Guide-2025-WEB_FINAL-WMS.pdf","title":"Global Initiative for Asthma (GINA) report, bản cập nhật hiện hành.","organization":null,"year_version":null,"citation":"Global Initiative for Asthma (GINA) report, bản cập nhật hiện hành.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-001-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Hen phế quản.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Hen phế quản.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Hen phế quản.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đợt cấp COPD","credit":"none"},{"text":"Tràn khí màng phổi tự phát","credit":"none"},{"text":"Cơn hen phế quản cấp nặng, nguy cơ suy hô hấp","credit":"full"},{"text":"Phản vệ có co thắt phế quản","credit":"none"}]},"action_options":[{"text":"Ngồi, monitor SpO2, thở oxy duy trì SpO2 93–95%","time_minutes":2,"grade":"critical","rationale":"Thiếu oxy máu cần sửa ngay; tránh quá liều oxy."},{"text":"Salbutamol 2,5–5 mg phun khí dung kèm ipratropium mỗi 20 phút trong giờ đầu","time_minutes":2,"grade":"critical","rationale":"Giãn phế quản nhanh là nền tảng xử trí cơn hen nặng."},{"text":"Corticoid toàn thân sớm (methylprednisolon tĩnh mạch hoặc prednisolon uống 40–50 mg)","time_minutes":2,"grade":"critical","rationale":"Giảm viêm đường thở, hiệu quả sau vài giờ nên cần cho sớm."},{"text":"Magnesium sulfat tĩnh mạch nếu đáp ứng kém sau giờ đầu","time_minutes":2,"grade":"critical","rationale":"Bổ sung giãn phế quản ở cơn nặng không đáp ứng."},{"text":"Theo dõi khí máu lặp lại và chuẩn bị chuyển hồi sức","time_minutes":2,"grade":"critical","rationale":"PaCO2 bình thường trong cơn nặng là dấu hiệu nguy hiểm."},{"text":"Kháng sinh thường quy","time_minutes":1,"grade":"waste","rationale":"Không có sốt, đờm mủ hay bằng chứng nhiễm khuẩn; cảm do virus là yếu tố khởi phát."},{"text":"Dùng thuốc an thần để giúp chị nghỉ ngơi","time_minutes":0,"grade":"harmful","rationale":"Ức chế hô hấp và có thể gây suy hô hấp đột ngột."}],"teaching_explanation":"Cơn hen nặng được nhận biết bằng nói từng từ, PEF dưới 50%, SpO2 giảm; PaCO2 bình thường khi đang thở nhanh là báo động suy hô hấp. Điều trị bằng oxy, đồng vận beta-2 và kháng cholinergic khí dung, corticoid toàn thân sớm, magnesium nếu kém đáp ứng."}'::jsonb,
  '130b8426bbe73b5b42e977f8e09c2ddb588d5b5d68af0d8ef8ea93c19daa179c'
)
