  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ho đờm mủ tăng, khó thở và lơ mơ ở người COPD","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":70,"sex":"nam","patient_label":"Ông C. H. B. (mô phỏng)"},"presentation":{"intro":"Ông được đưa vào cấp cứu vì khó thở tăng ba ngày, ho đờm vàng đục nhiều hơn và ngủ gà từ sáng.","place":null,"clock":null,"night":false},"vitals":{"hr":108,"sbp":142,"dbp":84,"rr":28,"temperature_c":37.9,"spo2":84},"history":[{"question":"Khó thở và ho đờm thay đổi thế nào trong 3 ngày?","response":"Khó thở tăng dần, đi vài bước đã thở dốc; ho nhiều, đờm chuyển từ trắng sang vàng đục và nhiều hơn gấp đôi."},{"question":"Có sốt, đau ngực, khò khè nhiều hơn không?","response":"Sốt nhẹ, khò khè nhiều; không đau ngực kiểu màng phổi."},{"question":"Tiền sử COPD, đợt cấp, nhập viện, thở oxy tại nhà?","response":"COPD 8 năm, GOLD nhóm E, 3 đợt cấp năm qua, một lần nhập viện; dùng tiotropium và formoterol/budesonid nhưng thỉnh thoảng bỏ liều; chưa dùng oxy tại nhà."},{"question":"Hút thuốc lá bao nhiêu?","response":"Hút 40 gói-năm, còn hút vài điếu mỗi ngày."},{"question":"Có lú lẫn, ngủ gà, đau đầu buổi sáng không?","response":"Từ sáng ngủ gà, hỏi chậm, gia đình lo lắng."},{"question":"Có phù chân, tăng cân, đau ngực, hồi hộp, tiền sử suy tim không?","response":"Phù nhẹ hai cổ chân, không suy tim đã biết."},{"question":"Đã tự dùng thuốc nào, có thở oxy lưu lượng cao tại nhà không?","response":"Xịt thuốc nhiều lần, không có oxy tại nhà."},{"question":"Dị ứng thuốc?","response":"Không dị ứng thuốc."}],"examination":[{"group":"K","item":"Hô hấp: nhịp thở và cơ hô hấp phụ","finding":"Thở 28 l/p, co kéo cơ hô hấp phụ, thở chúm môi, lồng ngực hình thùng."},{"group":"K","item":"Phổi nghe","finding":"Rì rào phế nang giảm, ran rít, ran ngáy hai phổi, vài ran ẩm đáy phải."},{"group":"K","item":"Tri giác","finding":"Ngủ gà nhưng gọi tỉnh, run vẫy tay (flapping), da hồng, giãn mạch ngoại vi."},{"group":"K","item":"Tim và phù","finding":"Tim nhanh đều 108 l/p, T2 mạnh ở ổ van động mạch phổi; phù nhẹ hai cổ chân."},{"group":"K","item":"Bụng","finding":"Mềm, không điểm đau."}],"investigations":[{"name":"Khí máu động mạch (ghi rõ FiO2)","duration_minutes":10,"result":"Khí trời: pH 7,29; PaO2 52 mmHg; PaCO2 68 mmHg; HCO3 32 mmol/L; lactate 1,6: toan hô hấp cấp trên nền tăng CO2 mạn."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Phổi tăng sáng, cơ hoành dẹt, nhóm mờ đáy phải; không tràn khí màng phổi."},{"name":"Công thức máu, CRP, điện giải, creatinin","duration_minutes":10,"result":"Bạch cầu 14,6 G/L, bạch cầu đa nhân 84%, CRP 62 mg/L; Hb 168 g/L; creatinin bình thường."},{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang nhanh 108 l/p, P phế (P cao ở DII), không rối loạn nhịp."},{"name":"Soi và cấy đờm; troponin, NT-proBNP","duration_minutes":10,"result":"Đờm mủ; troponin bình thường; NT-proBNP 410 pg/mL (không ủng hộ suy tim cấp)."},{"name":"CT mạch máu phổi cản quang cho mọi đợt cấp COPD","duration_minutes":40,"result":"Không có chỉ định thường quy nếu không nghi thuyên tắc; không ưu tiên."}],"choices":{"diagnosis":{"ydx":["Suy tim cấp phù phổi","Hen phế quản cơn nặng","Đợt cấp COPD nặng kèm suy hô hấp tăng CO2 cấp trên mạn do nhiễm khuẩn phế quản phổi","Thuyên tắc phổi cấp"]},"actions":["Kháng sinh theo kinh nghiệm (amoxicillin–clavulanat) và cấy đờm","Prednisolon 40 mg uống hoặc methylprednisolon tương đương trong 5 ngày","Thông khí không xâm nhập (BiPAP) vì pH 7,29 và PaCO2 68 với ngủ gà","Cho thở oxy lưu lượng cao 10 L/phút qua mặt nạ","Thở oxy Venturi mục tiêu SpO2 88–92%, monitor và lặp lại khí máu sau 30–60 phút","Phun khí dung salbutamol kèm ipratropium: mỗi giờ trong 2 đến 3 liều đầu, sau đó mỗi 2 đến 4 giờ theo đáp ứng","Tiêm thuốc an thần để dễ thở","Dùng thuốc lợi tiểu liều cao thường quy"]}}'::jsonb,
  'ff9b69ba658b4d982bc09577742c1f7afaaea6ff471bf9016e50f3b7383be98d'
)
