insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-ho-hap-002',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-002-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị bệnh phổi tắc nghẽn mạn tính, Bộ Y tế Việt Nam, 2018.","title":"Hướng dẫn chẩn đoán và điều trị bệnh phổi tắc nghẽn mạn tính, Bộ Y tế Việt Nam, 2018.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị bệnh phổi tắc nghẽn mạn tính, Bộ Y tế Việt Nam, 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-gold-2025-801096d6b722","resource_type":"guideline","source":"https://goldcopd.org/2025-gold-report/","title":"Global Initiative for Chronic Obstructive Lung Disease (GOLD) report, bản cập nhật hiện hành.","organization":null,"year_version":null,"citation":"Global Initiative for Chronic Obstructive Lung Disease (GOLD) report, bản cập nhật hiện hành.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-002-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh phổi tắc nghẽn mạn tính.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh phổi tắc nghẽn mạn tính.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Dược TPHCM, phần Bệnh phổi tắc nghẽn mạn tính.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hen phế quản cơn nặng","credit":"none"},{"text":"Thuyên tắc phổi cấp","credit":"none"},{"text":"Suy tim cấp phù phổi","credit":"none"},{"text":"Đợt cấp COPD nặng kèm suy hô hấp tăng CO2 cấp trên mạn do nhiễm khuẩn phế quản phổi","credit":"full"}]},"action_options":[{"text":"Thở oxy Venturi mục tiêu SpO2 88–92%, monitor và lặp lại khí máu sau 30–60 phút","time_minutes":2,"grade":"critical","rationale":"Tránh thở oxy quá mức làm nặng tăng CO2; cần kiểm tra khí máu."},{"text":"Thông khí không xâm nhập (BiPAP) vì pH 7,29 và PaCO2 68 với ngủ gà","time_minutes":2,"grade":"critical","rationale":"Giảm tử vong và đặt nội khí quản ở đợt cấp COPD toan hô hấp."},{"text":"Phun khí dung salbutamol kèm ipratropium: mỗi giờ trong 2 đến 3 liều đầu, sau đó mỗi 2 đến 4 giờ theo đáp ứng","time_minutes":2,"grade":"critical","rationale":"Giãn phế quản, giảm ứ khí."},{"text":"Prednisolon 40 mg uống hoặc methylprednisolon tương đương trong 5 ngày","time_minutes":2,"grade":"critical","rationale":"Rút ngắn thời gian hồi phục và giảm tái phát."},{"text":"Kháng sinh theo kinh nghiệm (amoxicillin–clavulanat) và cấy đờm","time_minutes":2,"grade":"critical","rationale":"Đờm mủ, khó thở và lượng đờm tăng (Anthonisen loại 1)."},{"text":"Dùng thuốc lợi tiểu liều cao thường quy","time_minutes":1,"grade":"waste","rationale":"Không có bằng chứng suy tim cấp; NT-proBNP thấp."},{"text":"Cho thở oxy lưu lượng cao 10 L/phút qua mặt nạ","time_minutes":0,"grade":"harmful","rationale":"Giảm đáp ứng hô hấp và tăng thông khí không tương xứng làm tăng CO2."},{"text":"Tiêm thuốc an thần để dễ thở","time_minutes":0,"grade":"harmful","rationale":"Ức chế hô hấp, có thể dẫn đến ngừng thở."}],"teaching_explanation":"Đợt cấp COPD có toan hô hấp cần oxy mục tiêu 88–92%, thông khí không xâm nhập khi pH dưới 7,35 kèm PaCO2 trên 45; điều trị bằng giãn phế quản, corticoid ngắn ngày và kháng sinh khi có dấu hiệu nhiễm khuẩn."}'::jsonb,
  'ac1ff33a9f9e13f7adb504ff810bedd8c84f0190605b40259518cf96fb9869bf'
)
