insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt, ho đờm rỉ sắt và đau ngực kiểu màng phổi","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":66,"sex":"nữ","patient_label":"Bà M. T. T. (mô phỏng)"},"presentation":{"intro":"Bà nhập khoa Nội vì sốt cao, ho đờm rỉ sắt và đau ngực bên phải bốn ngày.","place":null,"clock":null,"night":false},"vitals":{"hr":100,"sbp":120,"dbp":72,"rr":24,"temperature_c":38.9,"spo2":93},"history":[{"question":"Sốt và ho bắt đầu khi nào, đờm thế nào?","response":"Bốn ngày nay sốt rét run 38,5–39 độ C, ho đờm màu rỉ sắt."},{"question":"Có đau ngực không, đau thay đổi theo hơi thở?","response":"Đau nhói ngực phải dưới, tăng khi hít sâu và ho."},{"question":"Có khó thở, lú lẫn, tiểu ít không?","response":"Hơi khó thở khi đi lại; tỉnh táo, tiểu bình thường."},{"question":"Bệnh nền: COPD, tim, đái tháo đường, bệnh thận, ung thư?","response":"Tăng huyết áp, đái tháo đường típ 2 uống metformin; không COPD."},{"question":"Gần đây có nhập viện, dùng kháng sinh trong 90 ngày, hoặc ở cơ sở chăm sóc dài hạn không?","response":"Không nhập viện, không dùng kháng sinh gần đây."},{"question":"Có hút thuốc, uống rượu, sặc, bệnh thần kinh, nghiện không?","response":"Không hút thuốc, không rượu, không sặc."},{"question":"Tiêm vắc xin cúm và phế cầu?","response":"Chưa tiêm."},{"question":"Có tiếp xúc người ho kéo dài, nghi lao?","response":"Không."}],"examination":[{"group":"K","item":"Phổi","finding":"Nhịp thở 24 l/p, rung thanh tăng, gõ đục và ran nổ, hội chứng đông đặc vùng đáy phổi phải."},{"group":"K","item":"Tim và huyết áp","finding":"Tim nhanh đều 100 l/p, huyết áp 120/72 mmHg, không tiếng thổi."},{"group":"K","item":"Tri giác","finding":"Tỉnh táo, định hướng tốt."},{"group":"K","item":"Nhiệt độ, da","finding":"Nhiệt 38,9 độ C, mặt đỏ, môi khô, không tím."},{"group":"K","item":"Bụng, chân","finding":"Bụng mềm; chân không phù, không sưng đau."}],"investigations":[{"name":"X-quang ngực thẳng nghiêng","duration_minutes":10,"result":"Đông đặc thùy dưới phải, có hình ảnh phế quản hơi, góc sườn hoành phải hơi tù."},{"name":"Công thức máu, CRP, procalcitonin","duration_minutes":10,"result":"Bạch cầu 16,8 G/L, đa nhân 88%; CRP 148 mg/L; procalcitonin 1,2 ng/mL."},{"name":"Ure, creatinin, điện giải, glucose","duration_minutes":10,"result":"Ure 8,2 mmol/L, creatinin 92 µmol/L, Na 135, glucose 9,4 mmol/L."},{"name":"Cấy máu trước kháng sinh, soi và cấy đờm","duration_minutes":10,"result":"Gram dương cầu khuẩn đôi, cấy đang chờ; đờm đạt chuẩn."},{"name":"SpO2 và khí máu khi cần","duration_minutes":10,"result":"SpO2 93% khí trời, PaO2 68 mmHg."},{"name":"CT ngực cản quang ngay để xác định chẩn đoán","duration_minutes":40,"result":"Không cần ở viêm phổi điển hình khi X-quang đã rõ."}],"choices":{"diagnosis":{"ydx":["Viêm phổi cộng đồng thùy dưới phải, nguy cơ trung bình (CURB-65 2 điểm)","Thuyên tắc phổi nhồi máu phổi","Lao phổi tiến triển","Đợt cấp COPD"]},"actions":["Hạ sốt, bù dịch, kiểm soát đường huyết","Đánh giá đáp ứng sau 48–72 giờ","Dùng corticoid toàn thân thường quy","Nhập viện, thở oxy để duy trì SpO2 94–98% (chỉ định khi dưới 94%), đường truyền, theo dõi sinh hiệu","Chụp CT ngực cản quang ngay","Điều trị ngoại trú với thuốc ho","Kháng sinh sớm trong 4 giờ kể từ lúc đến viện (ceftriaxon + azithromycin); chỉ cấy máu và đờm khi có chỉ định (bệnh nặng, nguy cơ MRSA hoặc P. aeruginosa)"]}}'::jsonb,
  '586e0d1eebd8d5fa8ebf19cd7d71b8c48e0cf46f2cf5d0618df31ec99ed2eb58'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-ho-hap-003',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-003-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị viêm phổi cộng đồng ở người lớn, Bộ Y tế Việt Nam, 2016 và bản cập nhật.","title":"Hướng dẫn chẩn đoán và điều trị viêm phổi cộng đồng ở người lớn, Bộ Y tế Việt Nam, 2016 và bản cập nhật.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị viêm phổi cộng đồng ở người lớn, Bộ Y tế Việt Nam, 2016 và bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-cap-ats-idsa-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31573350/","title":"ATS/IDSA Guidelines for the diagnosis and treatment of adults with community-acquired pneumonia, 2019.","organization":null,"year_version":null,"citation":"ATS/IDSA Guidelines for the diagnosis and treatment of adults with community-acquired pneumonia, 2019.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-003-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Viêm phổi.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Viêm phổi.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Viêm phổi.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm phổi cộng đồng thùy dưới phải, nguy cơ trung bình (CURB-65 2 điểm)","credit":"full"},{"text":"Lao phổi tiến triển","credit":"none"},{"text":"Thuyên tắc phổi nhồi máu phổi","credit":"none"},{"text":"Đợt cấp COPD","credit":"none"}]},"action_options":[{"text":"Nhập viện, thở oxy để duy trì SpO2 94–98% (chỉ định khi dưới 94%), đường truyền, theo dõi sinh hiệu","time_minutes":2,"grade":"critical","rationale":"CURB-65 2 điểm cần nhập viện; SpO2 93% là dưới 94% nên cần oxy và theo dõi sát."},{"text":"Kháng sinh sớm trong 4 giờ kể từ lúc đến viện (ceftriaxon + azithromycin); chỉ cấy máu và đờm khi có chỉ định (bệnh nặng, nguy cơ MRSA hoặc P. aeruginosa)","time_minutes":2,"grade":"critical","rationale":"Điều trị đúng thuốc sớm giảm tử vong."},{"text":"Hạ sốt, bù dịch, kiểm soát đường huyết","time_minutes":2,"grade":"recommended","rationale":"Giảm triệu chứng và kiểm soát bệnh nền."},{"text":"Đánh giá đáp ứng sau 48–72 giờ","time_minutes":2,"grade":"recommended","rationale":"Phát hiện sớm thất bại điều trị."},{"text":"Dùng corticoid toàn thân thường quy","time_minutes":1,"grade":"waste","rationale":"Không có bằng chứng cho mọi viêm phổi cộng đồng không có sốc."},{"text":"Chụp CT ngực cản quang ngay","time_minutes":1,"grade":"waste","rationale":"Không cần thiết khi X-quang đủ chẩn đoán."},{"text":"Điều trị ngoại trú với thuốc ho","time_minutes":0,"grade":"harmful","rationale":"Bỏ qua điểm CURB-65 2 điểm, nguy cơ diễn tiến nặng."}],"teaching_explanation":"Viêm phổi cộng đồng điển hình được chẩn đoán bằng lâm sàng (sốt, ho đờm, hội chứng đông đặc) cộng X-quang; chọn nơi điều trị dựa vào PSI (ATS/IDSA ưu tiên) hoặc CURB-65 kèm đánh giá lâm sàng, kháng sinh sớm phù hợp và đánh giá lại kháng sinh tĩnh mạch sau 48 giờ (NICE)."}'::jsonb,
  '5145f7c557f0a37eb4f2976bc7bf13b20c5d78cbcad57a636f5bb17639589699'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở đột ngột, đau ngực kiểu màng phổi sau bó bột chân","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":52,"sex":"nam","patient_label":"Ông L. Q. V. (mô phỏng)"},"presentation":{"intro":"Ông đến cấp cứu vì khó thở đột ngột, đau ngực khi hít sâu, ba tuần sau khi bó bột gãy xương cẳng chân trái.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":118,"dbp":74,"rr":28,"temperature_c":37.4,"spo2":90},"history":[{"question":"Khó thở bắt đầu thế nào, có đột ngột không?","response":"Đột ngột cách đây 6 giờ khi đi vệ sinh, khó thở tăng dần."},{"question":"Đau ngực ra sao, có ho ra máu không?","response":"Đau nhói ngực phải khi hít sâu; ho khan, một lần khạc ít đờm lẫn máu."},{"question":"Có sưng đau bắp chân, chân to hơn một bên không?","response":"Cẳng chân trái bó bột ba tuần; ba ngày nay bàn chân và bắp chân sưng đau tăng, bột chật."},{"question":"Có ngất, choáng, hồi hộp không?","response":"Choáng khi đứng dậy, không ngất, hơi hồi hộp."},{"question":"Yếu tố nguy cơ huyết khối: bất động, phẫu thuật, ung thư, tiền sử huyết khối, hút thuốc?","response":"Bất động ba tuần; không phẫu thuật lớn; không ung thư; không tiền sử huyết khối; hút thuốc 15 gói-năm."},{"question":"Bệnh nền: tim, phổi, đái tháo đường, bệnh thận, dị ứng thuốc cản quang?","response":"Không bệnh tim phổi; không đái tháo đường; không dị ứng thuốc cản quang; thận bình thường."},{"question":"Đang dùng thuốc dự phòng huyết khối (enoxaparin) khi bó bột không?","response":"Không được dùng thuốc dự phòng."},{"question":"Có sốt, ho đờm mủ không?","response":"Không sốt, ho khan."}],"examination":[{"group":"K","item":"Hô hấp","finding":"Thở nhanh 28 l/p, phổi trong, ít ran ẩm đáy phải, không khò khè."},{"group":"K","item":"Tim","finding":"Nhịp nhanh đều 112 l/p, T2 mạnh ở ổ động mạch phổi, tĩnh mạch cổ nổi nhẹ, không tiếng thổi."},{"group":"K","item":"Chân","finding":"Cẳng chân trái sưng căng, đau khi sờ dọc tĩnh mạch sâu, chu vi lớn hơn bên phải 4 cm; bàn chân ấm."},{"group":"K","item":"Huyết động","finding":"Huyết áp 118/74 mmHg, không sốc, SpO2 90% khí trời."},{"group":"K","item":"Bụng","finding":"Mềm, không điểm đau."}],"investigations":[{"name":"Điện tim","duration_minutes":10,"result":"Nhịp xoang nhanh 112 l/p, T đảo V1–V3, dấu hiệu S1Q3T3."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,46; PaO2 58; PaCO2 31; A-a gradient tăng."},{"name":"hs-troponin, NT-proBNP, D-dimer, công thức máu, creatinin","duration_minutes":10,"result":"Troponin 38 ng/L hơi tăng; NT-proBNP 780; D-dimer 4,2 mg/L (không cần để loại trừ khi xác suất cao); creatinin 84 µmol/L."},{"name":"Siêu âm tim tại giường","duration_minutes":15,"result":"Thất phải giãn (tỉ lệ thất phải/thất trái 1,1), vách liên thất dẹt, TAPSE 14 mm."},{"name":"Siêu âm Doppler tĩnh mạch chi dưới","duration_minutes":15,"result":"Huyết khối tĩnh mạch khoeo và tĩnh mạch chày sau bên trái, không nén xẹp."},{"name":"CT mạch máu phổi (CTPA)","duration_minutes":40,"result":"Khuyết thuốc ở động mạch phổi thùy dưới phải và thùy giữa; thất phải giãn."},{"name":"Chụp mạch phổi chọn lọc qua catheter làm bước đầu thường quy","duration_minutes":10,"result":"Không phải đầu tay khi có CTPA, xâm lấn."}],"choices":{"diagnosis":{"ydx":["Thuyên tắc phổi cấp nguy cơ trung gian–cao, huyết khối tĩnh mạch sâu chi dưới trái","Tràn khí màng phổi tự phát","Viêm phổi cộng đồng","Nhồi máu cơ tim cấp"]},"actions":["Phân tầng bằng siêu âm tim, troponin, sPESI và nhập đơn vị theo dõi","Chụp CT mạch máu phổi và siêu âm Doppler chi dưới","Tiêu sợi huyết ngay cho mọi người bệnh","Dùng aspirin thay cho thuốc chống đông","Ngồi hoặc nằm đầu cao, monitor, thở oxy khi SpO2 dưới 90% (mục tiêu 94 đến 98%, hoặc 88 đến 92% nếu có nguy cơ tăng CO2)","Làm D-dimer để loại trừ thuyên tắc phổi","Bắt đầu chống đông ngay (enoxaparin 1 mg/kg tiêm dưới da mỗi 12 giờ hoặc UFH tĩnh mạch) trong khi chờ CTPA vì xác suất lâm sàng cao"]}}'::jsonb,
  '22af800852ba1ad8a52a52f743aa1a1a21f5dfaaaf76872f87c7bc55557c8add'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
