  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-pe-esc-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31504429/","title":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism, Eur Heart J 2020.","organization":null,"year_version":null,"citation":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism, Eur Heart J 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-004-2","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị thuyên tắc phổi, Hội Tim mạch học Việt Nam, bản cập nhật.","title":"Hướng dẫn chẩn đoán và điều trị thuyên tắc phổi, Hội Tim mạch học Việt Nam, bản cập nhật.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị thuyên tắc phổi, Hội Tim mạch học Việt Nam, bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-004-3","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh tim mạch và hô hấp.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh tim mạch và hô hấp.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Bệnh tim mạch và hô hấp.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"essential"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm phổi cộng đồng","credit":"none"},{"text":"Thuyên tắc phổi cấp nguy cơ trung gian–cao, huyết khối tĩnh mạch sâu chi dưới trái","credit":"full"},{"text":"Nhồi máu cơ tim cấp","credit":"none"},{"text":"Tràn khí màng phổi tự phát","credit":"none"}]},"action_options":[{"text":"Ngồi hoặc nằm đầu cao, monitor, thở oxy khi SpO2 dưới 90% (mục tiêu 94 đến 98%, hoặc 88 đến 92% nếu có nguy cơ tăng CO2)","time_minutes":2,"grade":"critical","rationale":"Giảm thiếu oxy máu, theo dõi huyết động liên tục."},{"text":"Bắt đầu chống đông ngay (enoxaparin 1 mg/kg tiêm dưới da mỗi 12 giờ hoặc UFH tĩnh mạch) trong khi chờ CTPA vì xác suất lâm sàng cao","time_minutes":2,"grade":"critical","rationale":"Điều trị sớm giảm tử vong; không chờ xác nhận khi xác suất cao và không chống chỉ định."},{"text":"Chụp CT mạch máu phổi và siêu âm Doppler chi dưới","time_minutes":2,"grade":"critical","rationale":"Xác nhận chẩn đoán và phân tầng nguy cơ."},{"text":"Phân tầng bằng siêu âm tim, troponin, sPESI và nhập đơn vị theo dõi","time_minutes":2,"grade":"critical","rationale":"Rối loạn thất phải cộng troponin tăng là nhóm nguy cơ trung gian–cao."},{"text":"Làm D-dimer để loại trừ thuyên tắc phổi","time_minutes":1,"grade":"waste","rationale":"Xác suất lâm sàng cao nên D-dimer âm tính không loại trừ."},{"text":"Tiêu sợi huyết ngay cho mọi người bệnh","time_minutes":0,"grade":"harmful","rationale":"Huyết động ổn định; tăng nguy cơ xuất huyết nặng không cần thiết."},{"text":"Dùng aspirin thay cho thuốc chống đông","time_minutes":0,"grade":"harmful","rationale":"Aspirin không đủ điều trị thuyên tắc phổi cấp."}],"teaching_explanation":"Thuyên tắc phổi cấp cần nghĩ tới khi khó thở đột ngột và có yếu tố nguy cơ; dùng điểm xác suất, CTPA, siêu âm tim và troponin để phân tầng. Chống đông ngay, tiêu sợi huyết chỉ khi huyết động không ổn định."}'::jsonb,
